function renderRankSection() {
  if (typeof document === "undefined") return;
  const container = document.getElementById("rank");
  if (!container) return;
  const currentRank = rankStatus.currentRank || "RECRUIT";
  const nextRank = getNextRankDefinition(currentRank);
  const promotionInput = buildCanonicalPromotionInput(currentRank, nextRank?.code || "CADET");
  const eligibility = evaluatePromotionEligibility(promotionInput, nextRank?.code || "CADET") || {
    status: "PROGRESSING",
    blockers: [],
    remainingActions: [],
    target: {},
    unresolvedConfirmedViolations: 0,
    consecutiveQualifyingWeeksRequired: 0
  };
  const evidence = buildPromotionEvidence({ ...promotionInput, nextRank: nextRank?.code || "CADET" });
  const review = generateAtlasPromotionReview({
    currentRank,
    nextRank: nextRank?.code || "CADET",
    status: eligibility.status,
    blockers: eligibility.blockers,
    remainingActions: eligibility.remainingActions,
    qualifyingHistory: `${promotionInput.finalizedInspections} finalized inspections available`,
    disciplineStandard: `Recent weekly discipline score target is ${eligibility.target?.minimumAverageDisciplineScore || 0}`,
    evidenceStandard: `Evidence coverage target is ${eligibility.target?.minimumAverageEvidenceCoverage || 0}%`,
    standardsRecord: `Confirmed standards issues: ${eligibility.unresolvedConfirmedViolations || 0}`,
    promotionOrder: "One rank at a time.",
    commandNote: nextRank ? `${nextRank.promotionCommandNote}` : "No additional rank remains."
  });
  setText("rank-current", currentRank);
  setText("rank-next", nextRank?.displayName || "—");
  setText("rank-status", eligibility.status);
  setText("rank-qualifying-weeks", String(eligibility.consecutiveQualifyingWeeksRequired || 0));
  const rankStateBadge = document.getElementById("rank-state");
  if (rankStateBadge) {
    rankStateBadge.textContent = eligibility.status;
    rankStateBadge.className = `state-pill ${eligibility.status === "ELIGIBLE" ? "green" : eligibility.status === "PROMOTED" ? "green" : eligibility.status === "PROGRESSING" ? "yellow" : eligibility.status === "BLOCKED" ? "red" : "neutral"}`;
  }
  const requirements = document.getElementById("rank-requirements");
  if (requirements) {
    requirements.innerHTML = evidence.requirements.map((item) => `<li>${item.requirement.replaceAll("_", " ")} — target ${item.target}, actual ${item.actual === null || !Number.isFinite(Number(item.actual)) ? "Insufficient evidence" : Math.round(Number(item.actual) * 10) / 10} (${item.passed ? "PASS" : "FAIL"})</li>`).join("");
  }
  const blockers = document.getElementById("rank-blockers");
  if (blockers) {
    blockers.innerHTML = eligibility.blockers.length ? eligibility.blockers.map((item) => `<div class="standards-item"><p>${item}</p></div>`).join("") : '<div class="standards-empty">No blockers detected.</div>';
  }
  const reviewOutput = document.getElementById("rank-review-output");
  if (reviewOutput) reviewOutput.textContent = review.text;
  const history = document.getElementById("rank-history");
  if (history) {
    const items = promotionHistory.length ? promotionHistory.map((item) => `<li class="feed-event info"><div class="feed-meta"><strong>${item.priorRank || "RECRUIT"} → ${item.currentRank || "CADET"}</strong><span>${item.promotionState || "PROMOTED"}</span></div><p>${item.effectiveDate || ""}</p></li>`).join("") : '<li class="feed-empty">No finalized promotions yet.</li>';
    history.innerHTML = items;
  }
  const ladder = document.getElementById("rank-ladder");
  if (ladder) {
    ladder.innerHTML = getRankCatalog().map((rank) => `<div class="standards-item"><div class="standards-item-header"><strong>${rank.displayName}</strong><span class="state-pill ${rank.code === currentRank ? "green" : "neutral"}">${rank.code}</span></div><p>${rank.description}</p><small>Min inspections ${rank.minimumFinalizedInspections}; min score ${rank.minimumAverageDisciplineScore}; evidence ${rank.minimumAverageEvidenceCoverage}%</small></div>`).join("");
  }
  renderReviewHub();
}

function renderStandardsSection() {
  if (typeof document === "undefined") return;
  const container = document.getElementById("standards");
  if (!container) return;
  const catalog = getStandardsCatalog();
  const items = mergeStandardsReviewItems(deriveStandardsReviewItems(dailyCompliance));
  const operations = deriveStandardsOperations(items);
  const patterns = detectStandardsPatterns(items);
  const openItems = [...operations.needsReview, ...operations.activeActions];
  const summaryState = openItems.length ? (openItems.some((item) => item.status === "CONFIRMED") ? "REVIEWING" : "MONITORING") : "CLEAR";
  setText("standards-catalog-count", catalog.length);
  setText("standards-candidate-count", openItems.length);
  setText("standards-confirmed-count", items.filter((item) => item.status === "CONFIRMED").length);
  setText("standards-resolved-count", items.filter((item) => item.status === "RESOLVED").length);
  const badge = document.getElementById("standards-state");
  if (badge) {
    badge.textContent = summaryState;
    badge.className = `state-pill ${summaryState === "REVIEWING" ? "yellow" : summaryState === "MONITORING" ? "neutral" : "green"}`;
  }
  setText("standards-review-count", operations.needsReview.length);
  setText("standards-active-count", operations.activeActions.length);
  setText("standards-closed-count", operations.resolved.length);
  const establishedPatterns = patterns.filter((pattern) => pattern.sufficient);
  const patternBadge = document.getElementById("standards-pattern-state");
  if (patternBadge) {
    patternBadge.textContent = establishedPatterns.length ? `${establishedPatterns.length} REVIEW` : patterns.length ? "INSUFFICIENT EVIDENCE" : "NO PATTERN";
    patternBadge.className = `state-pill ${establishedPatterns.length ? "yellow" : "neutral"}`;
  }
  const patternPanel = document.getElementById("standards-patterns");
  if (patternPanel) {
    patternPanel.innerHTML = patterns.length ? patterns.map((pattern) => `<article class="standards-pattern ${pattern.sufficient ? "established" : "insufficient"}">
      <div class="standards-item-header"><div><span class="kicker">${escapeHtml(pattern.standardCode)}</span><strong>${escapeHtml(pattern.domain)} pattern review</strong></div><span class="state-pill ${pattern.sufficient ? "yellow" : "neutral"}">${pattern.confidence}</span></div>
      <div class="standards-case-meta"><span>${pattern.caseCount} REVIEWED CASES</span><span>${pattern.distinctDateCount} DISTINCT DATES</span><span>${pattern.firstDate || "—"} → ${pattern.lastDate || "—"}</span></div>
      <p>${escapeHtml(pattern.recommendation)}</p>
      <small>Current severity remains ${escapeHtml(pattern.currentLevel)} until a human confirms any change.</small>
    </article>`).join("") : '<div class="standards-empty">No repeated reviewed standards cases are available for pattern analysis.</div>';
  }
  const renderCard = (item, lane) => {
    const standard = catalog.find((entry) => entry.code === (item.standardCode || standardsDomainCode(item.domain)));
    const actions = lane === "review"
      ? `<button type="button" class="ghost" data-standard-action="clarify" data-standard-id="${escapeHtml(item.id)}">Request context</button><button type="button" data-standard-action="confirm" data-standard-id="${escapeHtml(item.id)}">Confirm</button><button type="button" class="ghost" data-standard-action="excuse" data-standard-id="${escapeHtml(item.id)}">Excuse</button><button type="button" class="ghost" data-standard-action="dismiss" data-standard-id="${escapeHtml(item.id)}">Dismiss</button>`
      : lane === "active"
        ? `<button type="button" class="ghost" data-standard-action="save-plan" data-standard-id="${escapeHtml(item.id)}">Save plan</button>${item.status === "CONFIRMED" ? `<button type="button" data-standard-action="submit-evidence" data-standard-id="${escapeHtml(item.id)}">Submit evidence</button>` : `<button type="button" data-standard-action="resolve" data-standard-id="${escapeHtml(item.id)}">Approve resolution</button>`}`
        : "";
    return `<article class="standards-item standards-case">
      <div class="standards-item-header"><div><span class="kicker">${escapeHtml(item.standardCode || standardsDomainCode(item.domain))}</span><strong>${escapeHtml(item.title || standard?.title || "Standards review")}</strong></div><span class="state-pill ${item.status === "CONFIRMED" ? "yellow" : item.status === "RESOLVED" ? "green" : "neutral"}">${escapeHtml(item.status)}</span></div>
      <p>${escapeHtml(item.evidence || "No supporting evidence recorded.")}</p>
      <div class="standards-case-meta"><span>${escapeHtml(item.severity?.level || "LEVEL I")}</span><span>${item.evidenceConfidence} EVIDENCE</span><span>${item.ageDays}D OLD</span></div>
      ${item.protectedException ? `<p class="standards-protection">Protected context: ${escapeHtml(item.protectedException)}</p>` : ""}
      ${lane === "active" ? `<div class="standards-action-order">
        <div class="standards-action-heading"><strong>Corrective action plan</strong><span class="state-pill ${deriveCorrectiveActionStatus(item.correctiveAction) === "OVERDUE" ? "red" : deriveCorrectiveActionStatus(item.correctiveAction) === "AWAITING REVIEW" ? "yellow" : "neutral"}">${deriveCorrectiveActionStatus(item.correctiveAction)}</span></div>
        <p>${escapeHtml(item.correctiveAction?.description || selectCorrectiveAction({ classification: item.classification, severity: item.severity?.level, domain: item.domain }).description)}</p>
        <label>Due date<input type="date" data-standard-due value="${escapeHtml(item.correctiveAction?.dueDate || "")}"></label>
        <label>Success criteria<textarea rows="2" data-standard-criteria>${escapeHtml(item.correctiveAction?.successCriteria || "")}</textarea></label>
        <label>Completion evidence<textarea rows="3" data-standard-evidence placeholder="What was completed, where is the evidence, and what changed?">${escapeHtml(item.correctiveAction?.completionEvidence || "")}</textarea></label>
        ${item.correctiveAction?.completionSubmittedAt ? `<small>Submitted ${new Date(item.correctiveAction.completionSubmittedAt).toLocaleString()} for explicit review.</small>` : ""}
      </div>` : ""}
      ${actions ? `<div class="standards-controls">${actions}</div>` : ""}
    </article>`;
  };
  [
    ["standards-review-queue", operations.needsReview, "review", "No evidence requires a decision."],
    ["standards-active-queue", operations.activeActions, "active", "No confirmed corrective actions are active."],
    ["standards-resolved-queue", operations.resolved, "resolved", "No resolved cases yet."]
  ].forEach(([id, laneItems, lane, empty]) => {
    const element = document.getElementById(id);
    if (element) element.innerHTML = laneItems.length ? laneItems.map((item) => renderCard(item, lane)).join("") : `<div class="standards-empty">${empty}</div>`;
  });
  const catalogElement = document.getElementById("standards-catalog");
  if (catalogElement) catalogElement.innerHTML = catalog.map((standard) => `<article class="standards-item"><div class="standards-item-header"><strong>${escapeHtml(standard.title)}</strong><span>${escapeHtml(standard.code)}</span></div><p>${escapeHtml(standard.description)}</p><small>${escapeHtml(standard.evidenceRule)}</small></article>`).join("");
  const auditTrail = document.getElementById("standards-audit-trail");
  if (auditTrail) {
    const events = loadStandardsAuditEvents().slice().sort((left, right) => (right.createdAt || "").localeCompare(left.createdAt || ""));
    auditTrail.innerHTML = events.length
      ? events.map((event) => `<li class="feed-event info"><div class="feed-meta"><strong>${event.violationId || "Review"}</strong><span>${event.priorStatus} → ${event.newStatus}</span></div><p>${event.note || "Reviewed"}</p><time>${event.createdAt ? new Date(event.createdAt).toLocaleString() : "Pending"}</time></li>`).join("")
      : '<li class="feed-empty">Standards reviews are logged locally until a Supabase-backed audit table is applied.</li>';
  }
  renderTodayStandardsDuty();
  renderReviewHub();
}

function emptyComplianceDomains() {
  return Object.fromEntries(COMPLIANCE_DOMAINS.map((key) => [key, {
    status: null,
    target: "",
    actual: "",
    note: "",
    restriction: "",
    approvedModification: false
  }]));
}

function complianceDomainsFromRecord(record) {
  const domains = emptyComplianceDomains();
  if (!record) return domains;
  COMPLIANCE_DOMAINS.forEach((key) => {
    domains[key] = {
      status: normalizeComplianceStatus(record[`${key}_status`]),
      target: record[`${key}_target`] || "",
      actual: record[`${key}_actual`] || "",
      note: record[`${key}_note`] || "",
      restriction: record[`${key}_restriction`] || "",
      approvedModification: Boolean(record[`${key}_approved_modification`])
    };
  });
  return domains;
}

function complianceDomainRow(key) {
  return `
    <fieldset class="compliance-domain" data-domain="${key}">
      <legend><button class="domain-toggle" type="button" aria-expanded="true" data-domain-toggle="${key}">${COMPLIANCE_DOMAIN_LABELS[key]}</button></legend>
      <div class="compliance-domain-grid" data-domain-content="${key}">
        <label for="${key}_target">Assigned target
          <input id="${key}_target" name="${key}_target" maxlength="500" placeholder="What was assigned?">
        </label>
        <label for="${key}_status">Completion status
          <select id="${key}_status" name="${key}_status">
            <option value="">NOT ASSESSED</option>
            <option value="completed">COMPLETE</option>
            <option value="partial">PARTIAL</option>
            <option value="missed">MISSED</option>
            <option value="excused">EXCUSED</option>
            <option value="not_applicable">N/A</option>
          </select>
        </label>
        <label for="${key}_actual">Actual result
          <input id="${key}_actual" name="${key}_actual" maxlength="500" placeholder="What was completed or modified?">
        </label>
        <label for="${key}_note">User note
          <input id="${key}_note" name="${key}_note" maxlength="500" placeholder="Optional execution context">
        </label>
        <label class="compliance-restriction" for="${key}_restriction">Restriction or approved modification
          <input id="${key}_restriction" name="${key}_restriction" maxlength="500" placeholder="Readiness, medical, or approved adjustment">
        </label>
        <label class="compliance-check" for="${key}_approved_modification"><input id="${key}_approved_modification" name="${key}_approved_modification" type="checkbox"> Approved modification</label>
      </div>
    </fieldset>`;
}

function initializeComplianceForm() {
  const container = document.getElementById("compliance-domains");
  container.innerHTML = COMPLIANCE_DOMAINS.map(complianceDomainRow).join("");
  container.querySelectorAll(".domain-toggle").forEach((button) => {
    button.addEventListener("click", () => {
      const domain = button.dataset.domainToggle;
      const fieldset = container.querySelector(`[data-domain="${domain}"]`);
      const content = fieldset?.querySelector(`[data-domain-content="${domain}"]`);
      const expanded = button.getAttribute("aria-expanded") === "true";
      button.setAttribute("aria-expanded", String(!expanded));
      fieldset?.classList.toggle("collapsed", expanded);
      if (content) content.hidden = expanded;
    });
  });
}

function applyMissionComplianceDefaults(domains) {
  if (!dailyState || domains.mission.target) return domains;
  const readinessResult = evaluateOperationalReadiness(dailyState);
  const mission = generateMission(readinessResult);
  domains.mission.target = `${mission.title}: ${mission.detail}`;
  domains.mission.restriction = readinessResult.restrictions.join("; ");
  domains.mission.approvedModification = readinessResult.state !== "GREEN";
  return domains;
}

function readComplianceForm() {
  const form = document.getElementById("compliance-form");
  const values = new FormData(form);
  return Object.fromEntries(COMPLIANCE_DOMAINS.map((key) => [key, {
    status: normalizeComplianceStatus(values.get(`${key}_status`)),
    target: String(values.get(`${key}_target`) || "").trim(),
    actual: String(values.get(`${key}_actual`) || "").trim(),
    note: String(values.get(`${key}_note`) || "").trim(),
    restriction: String(values.get(`${key}_restriction`) || "").trim(),
    approvedModification: values.get(`${key}_approved_modification`) === "on"
  }]));
}

function renderComplianceScore(domains) {
  const state = deriveDailyComplianceState(domains);
  setText("discipline-score", state.displayScore);
  setText("compliance-status", state.complianceStatus);
  setText("compliance-formula", state.explanation.formula);
  setList("compliance-included", state.explanation.included, "No domains included.");
  setList("compliance-excluded", state.explanation.excluded, "No domains excluded.");
}

function updateComplianceStatusMessage() {
  const saveState = deriveSaveState(currentSaveState);
  const storageLabel = document.getElementById("compliance-storage");
  storageLabel.textContent = saveState.label.toUpperCase();
  storageLabel.className = `compliance-storage ${saveState.tone}`;
  const updatedLabel = document.getElementById("compliance-updated");
  updatedLabel.textContent = currentSaveState === "failed"
    ? "Save failed. Retry when connection is available."
    : currentSaveState === "locally saved"
      ? "Saved locally while remote sync is unavailable."
      : currentSaveState === "saving"
        ? "Saving record…"
        : currentSaveState === "saved"
          ? "Saved successfully."
          : "Not saved yet";
}

function setComplianceDirtyState(nextState = null) {
  const form = document.getElementById("compliance-form");
  if (!form) return;
  const values = nextState || readComplianceForm();
  complianceDirtyState = deriveDirtyState(compliancePreviousState || emptyComplianceDomains(), values);
  const saveButton = document.getElementById("save-compliance");
  if (saveButton) saveButton.disabled = !complianceDirtyState;
  form.dataset.dirty = complianceDirtyState ? "true" : "false";
}

function setComplianceDefaultsFromState(record) {
  const domains = applyMissionComplianceDefaults(complianceDomainsFromRecord(record));
  COMPLIANCE_DOMAINS.forEach((key) => {
    const fieldset = document.querySelector(`[data-domain="${key}"]`);
    if (fieldset) fieldset.classList.toggle("collapsed", false);
  });
  return domains;
}

function renderComplianceRecord(record, storageMode = "SUPABASE") {
  const domains = setComplianceDefaultsFromState(record);
  COMPLIANCE_DOMAINS.forEach((key) => {
    const domain = domains[key];
    const form = document.getElementById("compliance-form");
    form.elements[`${key}_status`].value = domain.status || "";
    form.elements[`${key}_target`].value = domain.target;
    form.elements[`${key}_actual`].value = domain.actual;
    form.elements[`${key}_note`].value = domain.note;
    form.elements[`${key}_restriction`].value = domain.restriction;
    form.elements[`${key}_approved_modification`].checked = domain.approvedModification;
  });
  compliancePreviousState = readComplianceForm();
  setComplianceDirtyState(compliancePreviousState);
  setText("compliance-date", record?.compliance_date || todayISODate());
  renderComplianceScore(domains);
  currentSaveState = storageMode === "LOCAL" ? "locally saved" : "saved";
  updateComplianceStatusMessage();
  lastSavedComplianceState = structuredClone(compliancePreviousState);
  renderStandardsSection();
}

function complianceStorageKey() {
  return `coach-dominion:daily-compliance:${session?.user?.id || "local"}:${todayISODate()}`;
}

function loadLocalCompliance() {
  try {
    const stored = window.localStorage.getItem(complianceStorageKey());
    return stored ? JSON.parse(stored) : null;
  } catch (_) {
    return null;
  }
}

function saveLocalCompliance(record) {
  try {
    window.localStorage.setItem(complianceStorageKey(), JSON.stringify(record));
    return true;
  } catch (_) {
    return false;
  }
}

async function loadDailyCompliance() {
  try {
    const supabase = await getClient();
    const { data, error } = await supabase
      .from("daily_compliance")
      .select(COMPLIANCE_COLUMNS)
      .eq("user_id", session.user.id)
      .eq("compliance_date", todayISODate())
      .maybeSingle();
    if (error) throw error;
    dailyCompliance = data;
    renderComplianceRecord(dailyCompliance, "SUPABASE");
    try {
      const remoteStandards = await loadStandardsReviewStateFromSupabase();
      standardsReviewState = remoteStandards.map((item) => normalizeRemoteStandardsItem(item));
      saveStandardsReviewState(standardsReviewState);
      saveStandardsAuditEvents([]);
    } catch (_) {
      // No remote standards state available; fall back to local state.
    }
  } catch (_) {
    dailyCompliance = loadLocalCompliance();
    renderComplianceRecord(dailyCompliance, "LOCAL");
    standardsReviewState = loadStandardsReviewState();
  }
}

function compliancePayload(domains) {
  const state = deriveDailyComplianceState(domains);
  const payload = {
    user_id: session?.user?.id || null,
    compliance_date: todayISODate(),
    discipline_score: state.score,
    score_evidence: { evidence: state.evidence, explanation: state.explanation, complianceStatus: state.complianceStatus }
  };
  COMPLIANCE_DOMAINS.forEach((key) => {
    payload[`${key}_status`] = domains[key].status;
    payload[`${key}_target`] = domains[key].target || null;
    payload[`${key}_actual`] = domains[key].actual || null;
    payload[`${key}_note`] = domains[key].note || null;
    payload[`${key}_restriction`] = domains[key].restriction || null;
    payload[`${key}_approved_modification`] = domains[key].approvedModification;
  });
  return payload;
}

async function saveDailyCompliance(event) {
  event.preventDefault();
  const button = document.getElementById("save-compliance");
  button.disabled = true;
  button.textContent = "Saving…";
  currentSaveState = "saving";
  updateComplianceStatusMessage();
  const payload = compliancePayload(readComplianceForm());
  try {
    const supabase = await getClient();
    const { data, error } = await supabase
      .from("daily_compliance")
      .upsert(payload, { onConflict: "user_id,compliance_date" })
      .select(COMPLIANCE_COLUMNS)
      .single();
    if (error) throw error;
    dailyCompliance = data;
    currentSaveState = "saved";
    renderComplianceRecord(data, "SUPABASE");
    try {
      await saveStandardsReviewStateToSupabase(standardsReviewState);
    } catch (_) {
      // Ignore remote standards persistence failure and continue with local fallback.
    }
  } catch (_) {
    const localRecord = { ...payload, updated_at: new Date().toISOString() };
    dailyCompliance = localRecord;
    const saved = saveLocalCompliance(localRecord);
    currentSaveState = saved ? "locally saved" : "failed";
    renderComplianceRecord(localRecord, "LOCAL");
    if (!saved) setText("compliance-storage", "UNSAVED — local storage unavailable");
  } finally {
    button.disabled = false;
    button.textContent = "Save Dominion Record";
    updateComplianceStatusMessage();
  }
  await loadTrendsAnalytics();
  const selectedWeek = getInspectionWeekRange(document.getElementById("weekly-date")?.value || todayISODate());
  if (todayISODate() >= selectedWeek.weekStartDate && todayISODate() <= selectedWeek.weekEndDate) {
    await loadWeeklyInspection();
  }
  renderDailyCoachingLoop();
}

function weeklyInspectionStorageKey(weekStartDate) {
  return `coach-dominion:weekly-inspection:${session?.user?.id || "local"}:${weekStartDate}`;
}

function loadLocalWeeklyInspection(weekStartDate) {
  try {
    const stored = window.localStorage.getItem(weeklyInspectionStorageKey(weekStartDate));
    return stored ? JSON.parse(stored) : null;
  } catch (_) {
    return null;
  }
}

function saveLocalWeeklyInspection(record) {
  try {
    window.localStorage.setItem(weeklyInspectionStorageKey(record.week_start_date), JSON.stringify(record));
    return true;
  } catch (_) {
    return false;
  }
}

function weeklyPlanStorageKey(nextWeekStart) {
  return `coach-dominion:weekly-plan:${session?.user?.id || "local"}:${nextWeekStart || "pending"}`;
}

function loadApprovedWeeklyPlan(nextWeekStart) {
  try { return JSON.parse(window.localStorage.getItem(weeklyPlanStorageKey(nextWeekStart)) || "null"); }
  catch (_) { return null; }
}

function renderWeeklyPlan(inspection = weeklyInspection) {
  const output = document.getElementById("weekly-plan-output");
  const status = document.getElementById("weekly-plan-status");
  if (!output || !status || typeof DominionWeeklyPlan === "undefined") return;
  const plan = DominionWeeklyPlan.buildWeeklyPlan(inspection);
  const approved = plan.nextWeekStart ? loadApprovedWeeklyPlan(plan.nextWeekStart) : null;
  const current = approved || plan;
  status.textContent = current.status;
  status.className = `state-pill ${current.status === "APPROVED" ? "green" : current.status === "READY FOR APPROVAL" ? "yellow" : "neutral"}`;
  if (!current.days?.length) {
    output.className = "performance-empty";
    output.textContent = current.reason;
    return;
  }
  output.className = "";
  const days = current.days.map((day) => `<article class="weekly-plan-day"><span>${escapeHtml(day.day)} · ${escapeHtml(day.date)}</span><strong>${escapeHtml(day.focus)}</strong><p>${escapeHtml(day.instruction)}</p></article>`).join("");
  output.innerHTML = `<div class="weekly-plan-header">
      <div><span>Next week</span><strong>${escapeHtml(current.nextWeekStart)} — ${escapeHtml(current.nextWeekEnd)}</strong></div>
      <div><span>Priority</span><strong>${escapeHtml(current.focus)}</strong></div>
      <div><span>Source discipline</span><strong>${formatDisciplineScore(current.disciplineScore)}</strong></div>
      <div><span>Source evidence</span><strong>${Math.round(current.evidenceCoverage)}%</strong></div>
    </div>
    <p><strong>Atlas priority:</strong> ${escapeHtml(current.priority.text)}</p>
    <div class="weekly-plan-days">${days}</div>
    <ul class="baseline-safeguards">${current.guardrails.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>
    <div class="weekly-plan-actions"><button type="button" data-weekly-plan-action="approve" ${current.status === "APPROVED" ? "disabled" : ""}>${current.status === "APPROVED" ? "Plan Approved" : "Approve Next Week’s Plan"}</button></div>`;
}

function approveCurrentWeeklyPlan() {
  if (!weeklyInspection || typeof DominionWeeklyPlan === "undefined") return;
  try {
    const plan = DominionWeeklyPlan.buildWeeklyPlan(weeklyInspection);
    const approved = DominionWeeklyPlan.approveWeeklyPlan(plan);
    window.localStorage.setItem(weeklyPlanStorageKey(approved.nextWeekStart), JSON.stringify(approved));
    renderWeeklyPlan(weeklyInspection);
    setText("weekly-plan-feedback", "Plan approved. Daily readiness and pain rules still govern each day.");
  } catch (error) {
    setText("weekly-plan-feedback", error.message);
  }
}

function loadLocalWeekRecords(range) {
  const records = [];
  try {
    for (let offset = 0; offset < 7; offset += 1) {
      const date = formatISODateUTC(addUTCDays(parseISODateUTC(range.weekStartDate), offset));
      const key = `coach-dominion:daily-compliance:${session?.user?.id || "local"}:${date}`;
      const stored = window.localStorage.getItem(key);
      if (stored) records.push(JSON.parse(stored));
    }
  } catch (_) {
    return records;
  }
  return records;
}

function resolveWeeklyInspectionLoadOutcome(input = {}) {
  if (input.savedInspection?.finalized_at && !input.inspectionReadError) {
    return { mode: "FINALIZED_REMOTE", storageMode: "SUPABASE", inspection: input.savedInspection, records: [], warning: "" };
  }
  if (!input.recordsReadError && Array.isArray(input.remoteRecords)) {
    const warnings = [];
    if (input.inspectionReadError) warnings.push(`Weekly snapshot storage is unavailable (${input.inspectionReadError.message || "unknown error"}).`);
    if (input.draftWriteError) warnings.push(`The live inspection was calculated, but its draft snapshot was not saved (${input.draftWriteError.message || "unknown error"}).`);
    return { mode: "REMOTE_RECORDS", storageMode: "SUPABASE", inspection: null, records: input.remoteRecords, warning: warnings.join(" ") };
  }
  if (input.savedInspection?.finalized_at) {
    return { mode: "FINALIZED_LOCAL", storageMode: "LOCAL", inspection: input.savedInspection, records: [], warning: "Remote weekly data is unavailable. Showing the finalized local snapshot." };
  }
  const localRecords = Array.isArray(input.localRecords) ? input.localRecords : [];
  return {
    mode: "LOCAL_RECORDS",
    storageMode: "LOCAL",
    inspection: null,
    records: localRecords,
    warning: localRecords.length
      ? `Remote Dominion Records could not be loaded (${input.recordsReadError?.message || "unknown error"}). Showing local fallback.`
      : `Remote Dominion Records could not be loaded (${input.recordsReadError?.message || "unknown error"}). No local fallback rows were found.`
  };
}

function weeklyPersistencePayload(aggregate, finalizedAt = null) {
  const report = aggregate.atlasReport || generateWeeklyAfterActionReport(aggregate);
  return {
    user_id: session?.user?.id || null,
    week_start_date: aggregate.weekStartDate,
    week_end_date: aggregate.weekEndDate,
    inspection_status: finalizedAt ? "inspection_complete" : aggregate.inspectionStatus.toLowerCase().replaceAll(" ", "_"),
    weekly_discipline_score: aggregate.score,
    evidence_coverage: aggregate.evidenceCoverage,
    domain_scores: aggregate.domainScores,
    aggregate_counts: aggregate.counts,
    strongest_domain: aggregate.strongestDomain,
    weakest_domain: aggregate.weakestDomain,
    next_week_priority: aggregate.nextWeekPriority,
    report_evidence: aggregate,
    atlas_report: report,
    finalized_at: finalizedAt
  };
}

function aggregateFromStoredInspection(record) {
  if (!record?.report_evidence) return null;
  const aggregate = structuredClone(record.report_evidence);
  aggregate.finalizedAt = record.finalized_at || aggregate.finalizedAt;
  aggregate.inspectionStatus = record.finalized_at ? "INSPECTION COMPLETE" : aggregate.inspectionStatus;
  aggregate.atlasReport = record.atlas_report || aggregate.atlasReport || generateWeeklyAfterActionReport(aggregate);
  return aggregate;
}

function renderWeeklyInspection(aggregate, storageMode) {
  weeklyInspection = aggregate;
  const finalized = Boolean(aggregate.finalizedAt);
  const finalizeState = deriveFinalizeConfirmationState(finalized, aggregate.evidenceCoverage);
  const label = (key) => key ? COMPLIANCE_DOMAIN_LABELS[key] : "UNSCORED";
  setText("weekly-status", aggregate.inspectionStatus);
  document.getElementById("weekly-status").className = `state-pill ${aggregate.inspectionStatus === "INSPECTION COMPLETE" ? "green" : aggregate.inspectionStatus === "READY FOR INSPECTION" ? "yellow" : "neutral"}`;
  setText("weekly-range", `${aggregate.weekStartDate} — ${aggregate.weekEndDate}`);
  setText("weekly-score", `${formatDisciplineScore(aggregate.score)}${aggregate.score !== null && aggregate.scoreIsProvisional ? " · PROVISIONAL" : ""}`);
  setText("weekly-coverage", `${Math.round(aggregate.evidenceCoverage)}%`);
  setText("weekly-storage", storageMode === "SUPABASE" ? "SUPABASE" : "LOCAL FALLBACK");
  setText("weekly-assessed-days", `${aggregate.counts.assessedDays} / ${aggregate.counts.fullyAssessedDays}`);
  setText("weekly-unscored-days", aggregate.counts.unscoredDays);
  setText("weekly-result-counts", `${aggregate.counts.completed} / ${aggregate.counts.partial} / ${aggregate.counts.missed}`);
  setText("weekly-excluded-counts", `${aggregate.counts.excused} / ${aggregate.counts.notApplicable}`);
  setText("weekly-modification-count", aggregate.counts.approvedModifications);
  setText("weekly-evidence-through", aggregate.evidenceThroughDate || "Week not started");
  setText("weekly-projected-coverage", `${Math.round(aggregate.projectedFullWeekCoverage || 0)}%`);
  setText("weekly-calculation-meta", `${aggregate.calculationVersion || INSPECTION_CALCULATION_VERSION} · ${aggregate.elapsedDayCount || 0}/7 days elapsed`);
  setText("weekly-strongest", aggregate.strongestDomains.length ? aggregate.strongestDomains.map(label).join(" / ") : "UNSCORED");
  setText("weekly-weakest", aggregate.domainRankingTie ? "NO DISTINCT WEAKEST — TIED" : aggregate.weakestDomains.length ? aggregate.weakestDomains.map(label).join(" / ") : "UNSCORED");
  setText("weekly-missed", aggregate.missedRequirements.length ? aggregate.missedRequirements.map((item) => `${item.date} ${label(item.domain)}`).join("; ") : "None recorded.");
  setText("weekly-excused", aggregate.excusedConditions.length ? aggregate.excusedConditions.map((item) => `${item.date} ${label(item.domain)}: ${item.restriction}`).join("; ") : "None recorded.");
  document.getElementById("weekly-domain-scores").innerHTML = COMPLIANCE_DOMAINS.map((key) => `<div><span>${COMPLIANCE_DOMAIN_LABELS[key]}</span><strong>${formatDisciplineScore(aggregate.domainScores[key].score)}</strong></div>`).join("");
  renderWeeklyCloseoutEvidence({ weekStartDate: aggregate.weekStartDate, weekEndDate: aggregate.weekEndDate });
  document.getElementById("weekly-evidence").innerHTML = aggregate.dailyEvidence.map((day) => `<details class="weekly-evidence-day ${day.periodState === "FUTURE" ? "future" : day.assessedCount ? "neutral" : "missing"}"><summary><strong>${day.date}</strong><span>${day.periodState === "FUTURE" ? "FUTURE · NOT COUNTED" : `${day.assessedCount}/5 ASSESSED`}</span></summary><p>${day.periodState === "FUTURE" ? "Excluded from current inspection evidence." : `${day.includedCount} applicable scoring observations`}</p></details>`).join("");
  setText("weekly-report", (aggregate.atlasReport || generateWeeklyAfterActionReport(aggregate)).text);
  renderWeeklyBodyOutcome(aggregate);
  const weeklyStandardsSummary = document.getElementById("weekly-standards-summary");
  const weeklyStandardsItems = standardsReviewState.filter((item) => item.sourceDate && item.sourceDate <= aggregate.weekEndDate && item.sourceDate >= aggregate.weekStartDate);
  if (weeklyStandardsSummary) {
    weeklyStandardsSummary.innerHTML = weeklyStandardsItems.length
      ? weeklyStandardsItems.map((item) => `<article class="standards-item"><div class="standards-item-header"><strong>${item.domain}</strong><span class="state-pill ${item.status === "CONFIRMED" ? "green" : item.status === "RESOLVED" ? "neutral" : item.status === "DISMISSED" ? "neutral" : item.status === "EXCUSED" ? "neutral" : "yellow"}">${item.status || "CANDIDATE"}</span></div><p>${item.evidence || "No evidence recorded."}</p><small>${item.severity?.level || "LEVEL I"}</small></article>`).join("")
      : '<div class="standards-empty">No standards review history for this inspection week.</div>';
  }
  const missingLabels = (aggregate.missingRequiredDomains || []).map(label);
  const warning = finalized
    ? `Finalized ${new Date(aggregate.finalizedAt).toLocaleString()}. Historical snapshot is read-only.`
    : aggregate.scoreIsProvisional
      ? `Provisional inspection. Evidence is measured only through ${aggregate.evidenceThroughDate || "the week start"}${missingLabels.length ? `; incomplete required domains: ${missingLabels.join(", ")}` : ""}${!aggregate.weekComplete ? "; the week is still in progress" : ""}.`
      : "";
  setText("weekly-warning", warning);
  const finalizeButton = document.getElementById("finalize-week");
  finalizeButton.disabled = finalized || !aggregate.canFinalize;
  finalizeButton.textContent = finalized ? "Inspection Finalized" : "Finalize Inspection";
  finalizeButton.setAttribute("aria-disabled", finalizeButton.disabled ? "true" : "false");
  const finalizeHint = document.getElementById("weekly-finalize-hint");
  if (finalizeHint) finalizeHint.textContent = finalized ? "This inspection is finalized and read-only." : finalizeState.readOnlyMessage;
  const inspectionSection = document.getElementById("inspection");
  if (inspectionSection) inspectionSection.dataset.finalized = finalized ? "true" : "false";
  renderCommandCenterOverview(dailyState ? evaluateReadiness(dailyState) : null, aggregate);
  renderWeeklyPlan(aggregate);
  renderStandardsSection();
  renderActivationGuide();
  renderReviewHub();
}

async function loadWeeklyInspectionLegacy() {
  const selectedDate = document.getElementById("weekly-date").value || todayISODate();
  const range = getInspectionWeekRange(selectedDate);
  setText("weekly-warning", "Calculating weekly evidence…");
  try {
    const supabase = await getClient();
    const { data: saved, error: inspectionError } = await supabase.from("weekly_inspections").select("*").eq("user_id", session.user.id).eq("week_start_date", range.weekStartDate).maybeSingle();
    if (inspectionError) throw inspectionError;
    if (saved?.finalized_at) {
      renderWeeklyInspection(aggregateFromStoredInspection(saved), "SUPABASE");
      return;
    }
    const { data: records, error: recordsError } = await supabase.from("daily_compliance").select(COMPLIANCE_COLUMNS).eq("user_id", session.user.id).gte("compliance_date", range.weekStartDate).lte("compliance_date", range.weekEndDate);
    if (recordsError) throw recordsError;
    weeklyDailyRecords = records || [];
    const aggregate = aggregateWeeklyCompliance(weeklyDailyRecords, range.weekStartDate);
    aggregate.atlasReport = generateWeeklyAfterActionReport(aggregate);
    const payload = weeklyPersistencePayload(aggregate);
    const { error: draftError } = await supabase.from("weekly_inspections").upsert(payload, { onConflict: "user_id,week_start_date" });
    if (draftError) throw draftError;
    renderWeeklyInspection(aggregate, "SUPABASE");
  } catch (error) {
    const saved = loadLocalWeeklyInspection(range.weekStartDate);
    if (saved?.finalized_at) {
      setText("weekly-warning", `Remote weekly inspection data could not be loaded (${error?.message || "unknown error"}). Showing the finalized local snapshot.`);
      renderWeeklyInspection(aggregateFromStoredInspection(saved), "LOCAL");
      return;
    }
    weeklyDailyRecords = loadLocalWeekRecords(range);
    const aggregate = aggregateWeeklyCompliance(weeklyDailyRecords, range.weekStartDate);
    aggregate.atlasReport = generateWeeklyAfterActionReport(aggregate);
    saveLocalWeeklyInspection(weeklyPersistencePayload(aggregate));
    const message = weeklyDailyRecords.length
      ? `Remote weekly inspection data could not be loaded (${error?.message || "unknown error"}). Showing local fallback.`
      : `Remote weekly inspection data could not be loaded (${error?.message || "unknown error"}). No local fallback rows were found.`;
    setText("weekly-warning", message);
    renderWeeklyInspection(aggregate, "LOCAL");
  }
}

async function loadWeeklyInspection() {
  const selectedDate = document.getElementById("weekly-date").value || todayISODate();
  const range = getInspectionWeekRange(selectedDate);
  setText("weekly-warning", "Calculating weekly evidence…");
  const supabase = await getClient();
  const inspectionResult = await supabase.from("weekly_inspections").select("*").eq("user_id", session.user.id).eq("week_start_date", range.weekStartDate).maybeSingle();
  if (inspectionResult.data?.finalized_at && !inspectionResult.error) {
    renderWeeklyInspection(aggregateFromStoredInspection(inspectionResult.data), "SUPABASE");
    return;
  }

  const recordsResult = await supabase.from("daily_compliance").select(COMPLIANCE_COLUMNS).eq("user_id", session.user.id).gte("compliance_date", range.weekStartDate).lte("compliance_date", range.weekEndDate);

  const localSaved = loadLocalWeeklyInspection(range.weekStartDate);
  const outcome = resolveWeeklyInspectionLoadOutcome({
    savedInspection: inspectionResult.data || localSaved,
    inspectionReadError: inspectionResult.error,
    remoteRecords: recordsResult.data,
    recordsReadError: recordsResult.error,
    draftWriteError: null,
    localRecords: loadLocalWeekRecords(range)
  });
  if (outcome.mode === "FINALIZED_LOCAL") {
    renderWeeklyInspection(aggregateFromStoredInspection(outcome.inspection), outcome.storageMode);
    setText("weekly-warning", outcome.warning);
    return;
  }
  weeklyDailyRecords = outcome.records;
  const aggregate = aggregateWeeklyCompliance(weeklyDailyRecords, range.weekStartDate);
  aggregate.atlasReport = generateWeeklyAfterActionReport(aggregate);
  if (outcome.storageMode === "LOCAL") saveLocalWeeklyInspection(weeklyPersistencePayload(aggregate));
  renderWeeklyInspection(aggregate, outcome.storageMode);
  if (outcome.warning) setText("weekly-warning", outcome.warning);
}

async function finalizeWeeklyInspection() {
  if (!weeklyInspection) return;
  const finalizeState = deriveFinalizeConfirmationState(Boolean(weeklyInspection.finalizedAt), weeklyInspection.evidenceCoverage);
  if (!finalizeState.canFinalize || !weeklyInspection.canFinalize) {
    setText("weekly-warning", !weeklyInspection.weekComplete ? "Finalization is available after the inspection week ends." : "Finalization requires sufficient evidence across every required domain.");
    return;
  }
  const confirmed = window.confirm(`${finalizeState.readOnlyMessage}\n\nFinalize this inspection now?`);
  if (!confirmed) return;
  const button = document.getElementById("finalize-week");
  button.disabled = true;
  try {
    const finalized = finalizeWeeklyInspectionSnapshot(weeklyInspection);
    const payload = weeklyPersistencePayload(finalized, finalized.finalizedAt);
    try {
      const supabase = await getClient();
      const { data, error } = await supabase.from("weekly_inspections").upsert(payload, { onConflict: "user_id,week_start_date" }).select("*").single();
      if (error) throw error;
      renderWeeklyInspection(aggregateFromStoredInspection(data), "SUPABASE");
    } catch (_) {
      saveLocalWeeklyInspection(payload);
      renderWeeklyInspection(finalized, "LOCAL");
    }
    await loadTrendsAnalytics();
  } catch (error) {
    setText("weekly-warning", error.message);
    button.disabled = false;
  }
}

function loadLocalAnalyticsHistory() {
  const user = session?.user?.id || "local";
  const dailyPrefix = `coach-dominion:daily-compliance:${user}:`;
  const weeklyPrefix = `coach-dominion:weekly-inspection:${user}:`;
  const dailyRecords = [];
  const inspections = [];
  try {
    for (let index = 0; index < window.localStorage.length; index += 1) {
      const key = window.localStorage.key(index);
      if (!key) continue;
      const parsed = JSON.parse(window.localStorage.getItem(key));
      if (key.startsWith(dailyPrefix)) dailyRecords.push(parsed);
      if (key.startsWith(weeklyPrefix)) inspections.push(parsed);
    }
  } catch (_) {
    return { dailyRecords, inspections };
  }
  return { dailyRecords, inspections };
}

function signedDisplay(value, suffix = "%") {
  if (!Number.isFinite(Number(value))) return "—";
  const rounded = Math.round(Number(value));
  return `${rounded > 0 ? "+" : ""}${rounded}${suffix}`;
}

function renderTrendChart(elementId, series, valueKey, label) {
  const element = document.getElementById(elementId);
  const points = series.filter((item) => isFiniteMetric(item[valueKey]));
  if (!points.length) {
    element.innerHTML = `<div class="chart-empty">No ${label.toLowerCase()} data available.</div>`;
    return;
  }
  const width = window.innerWidth < 640 ? 320 : 640;
  const height = window.innerWidth < 640 ? 210 : 230;
  const left = 42;
  const right = 18;
  const top = 18;
  const bottom = 48;
  const x = (index) => points.length === 1 ? width / 2 : left + index * ((width - left - right) / (points.length - 1));
  const y = (value) => top + (100 - Math.max(0, Math.min(100, Number(value)))) / 100 * (height - top - bottom);
  const finalized = points.filter((item) => item.kind === "FINALIZED");
  const finalizedCoordinates = finalized.map((item) => `${x(points.indexOf(item))},${y(item[valueKey])}`).join(" ");
  const provisional = points.find((item) => item.kind === "PROVISIONAL");
  const prior = provisional ? points.slice(0, points.indexOf(provisional)).at(-1) : null;
  const provisionalLine = provisional && prior ? `<line class="chart-line chart-provisional-line" x1="${x(points.indexOf(prior))}" y1="${y(prior[valueKey])}" x2="${x(points.indexOf(provisional))}" y2="${y(provisional[valueKey])}"></line>` : "";
  const grid = [0, 25, 50, 75, 100].map((value) => `<line class="chart-gridline" x1="${left}" y1="${y(value)}" x2="${width - right}" y2="${y(value)}"></line><text class="chart-label" x="4" y="${y(value) + 4}">${value}</text>`).join("");
  const marks = points.map((item, index) => {
    const weakEvidence = valueKey === "score" && Number(item.evidenceCoverage) < TREND_EVIDENCE_THRESHOLD;
    return `<circle class="chart-point ${item.kind === "PROVISIONAL" ? "provisional" : ""} ${weakEvidence ? "weak-evidence" : ""}" cx="${x(index)}" cy="${y(item[valueKey])}" r="5"><title>${item.weekStartDate}: ${item[valueKey]}% ${item.kind.toLowerCase()}${weakEvidence ? "; limited evidence" : ""}</title></circle><text class="chart-label" text-anchor="middle" x="${x(index)}" y="${height - 25}">${item.weekStartDate.slice(5)}</text><text class="chart-label" text-anchor="middle" x="${x(index)}" y="${y(item[valueKey]) - 9}">${Math.round(item[valueKey])}</text>`;
  }).join("");
  const equivalent = points.map((item) => `${item.weekStartDate}: ${item[valueKey]}% (${item.kind.toLowerCase()}${valueKey === "score" && Number(item.evidenceCoverage) < TREND_EVIDENCE_THRESHOLD ? ", limited evidence" : ""})`).join("; ");
  element.innerHTML = `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${label}. Fixed axis from zero to one hundred percent.">${grid}${finalizedCoordinates ? `<polyline class="chart-line" points="${finalizedCoordinates}"></polyline>` : ""}${provisionalLine}${marks}</svg><p class="chart-equivalent">${equivalent}</p>`;
}

function renderLegacyTrendsAnalytics(inspections, dailyRecords, storageMode) {
  inspectionHistory = canonicalFinalizedInspections(inspections);
  const currentRange = getInspectionWeekRange(todayISODate());
  const currentAggregate = aggregateWeeklyCompliance(dailyRecords, currentRange.weekStartDate);
  const hasFinalizedCurrentWeek = sortInspectionHistory(inspections).some((item) => item.weekStartDate === currentRange.weekStartDate && item.finalizedAt);
  const provisional = currentAggregate.counts.assessedObservations > 0 && !hasFinalizedCurrentWeek ? currentAggregate : null;
  const trajectory = deriveTrajectoryState(inspectionHistory);
  const domainTrends = calculateDomainTrends(inspectionHistory);
  const streaks = calculateComplianceStreaks(dailyRecords, todayISODate());
  const summary = summarizeInspectionHistory(inspectionHistory);
  const chartSeries = buildChartSeries(inspectionHistory, provisional);
  const report = generateAtlasTrendReport({ trajectory, domainTrends, streaks, summary, chartSeries });
  setText("trajectory-status", trajectory.state);
  document.getElementById("trajectory-status").className = `state-pill ${trajectory.state === "IMPROVING" ? "green" : trajectory.state === "DECLINING" ? "red" : trajectory.state === "LIMITED EVIDENCE" ? "yellow" : "neutral"}`;
  setText("analytics-storage", `${storageMode} ANALYTICS — derived, not stored`);
  setText("trend-summary-trajectory", trajectory.state || "INSUFFICIENT HISTORY");
  setText("trend-summary-score-change", signedDisplay(summary.scoreChange));
  setText("trend-summary-evidence", trajectory.averageEvidence === null ? "—" : `${Math.round(trajectory.averageEvidence)}%`);
  const domainAtRisk = report.domainAtRisk === "No declining domain established." ? "—" : report.domainAtRisk;
  setText("trend-summary-domain", domainAtRisk);
  setText("trend-summary-consistency", report.consistency || "—");
  const windowDates = trajectory.window.map((item) => item.weekStartDate);
  setText("trend-window", windowDates.length ? `Finalized trend window: ${windowDates[0]} through ${windowDates.at(-1)} (${windowDates.length} scored weeks).` : "No finalized scored trend window available.");
  setText("trend-latest-score", summary.mostRecentFinalized ? formatDisciplineScore(summary.mostRecentFinalized.score) : "UNSCORED");
  setText("trend-average-score", formatDisciplineScore(summary.recentAverageScore));
  setText("trend-score-change", signedDisplay(summary.scoreChange));
  setText("trend-evidence-change", signedDisplay(summary.evidenceChange));
  setText("trend-best-week", summary.bestWeek ? `${summary.bestWeek.weekStartDate} // ${formatDisciplineScore(summary.bestWeek.score)}` : "—");
  setText("trend-lowest-week", summary.lowestWeek ? `${summary.lowestWeek.weekStartDate} // ${formatDisciplineScore(summary.lowestWeek.score)}` : "—");
  setText("trend-finalized-count", summary.finalizedCount);
  setText("trend-completion-rate", Number.isFinite(summary.recentInspectionCompletionRate) ? `${Math.round(summary.recentInspectionCompletionRate)}%` : "—");
  setText("current-assessed-streak", `${streaks.currentAssessedDayStreak} days`);
  setText("current-full-streak", `${streaks.currentFullyAssessedDayStreak} days`);
  setText("longest-assessed-streak", `${streaks.longestAssessedDayStreak} days`);
  document.getElementById("trend-domain-grid").innerHTML = COMPLIANCE_DOMAINS.map((key) => `<div class="trend-domain-card ${domainTrends[key].direction.toLowerCase().replaceAll(" ", "-")}"><span>${COMPLIANCE_DOMAIN_LABELS[key]}</span><strong>${domainTrends[key].direction}</strong><small>${domainTrends[key].slope === null ? "No reliable slope" : `${domainTrends[key].slope.toFixed(2)} pts/week`}</small></div>`).join("");
  renderTrendChart("discipline-trend-chart", chartSeries, "score", "Weekly Discipline Score");
  renderTrendChart("evidence-trend-chart", chartSeries, "evidenceCoverage", "Weekly Evidence Coverage");
  setText("atlas-trend-report", report.text);
  renderCommandCenterOverview(dailyState ? evaluateReadiness(dailyState) : null, weeklyInspection || {}, trajectory.state);
  renderRankSection();
  renderReviewHub();
}

function trendPreferenceKey() {
  return `coach-dominion:trends-view:${session?.user?.id || "local"}`;
}

function loadTrendPreferences() {
  try {
    const stored = JSON.parse(window.localStorage.getItem(trendPreferenceKey()) || "null");
    if (typeof DominionTrends !== "undefined") trendRangeDays = DominionTrends.normalizeRangeDays(stored?.rangeDays);
    trendActiveView = ["overview", "training", "recovery", "body"].includes(stored?.view) ? stored.view : "overview";
    trendActiveMetric = ["discipline", "readiness", "weight"].includes(stored?.metric) ? stored.metric : "discipline";
    trendBodyMetric = ["waist", "neck", "chest", "hips", "arm", "thigh", "body_fat"].includes(stored?.bodyMetric) ? stored.bodyMetric : "waist";
  } catch (_) {
    trendRangeDays = 28;
    trendActiveView = "overview";
    trendActiveMetric = "discipline";
    trendBodyMetric = "waist";
  }
}

function saveTrendPreferences() {
  try {
    window.localStorage.setItem(trendPreferenceKey(), JSON.stringify({
      rangeDays: trendRangeDays,
      view: trendActiveView,
      metric: trendActiveMetric,
      bodyMetric: trendBodyMetric
    }));
  } catch (_) {}
}

function trendNutritionHistory(rangeDays = 84) {
  const imported = connectedApi() ? connectedApi().aggregateNutritionByDate(connectedImportedRecords) : [];
  const importedByDate = new Map(imported.map((item) => [item.date, { ...item, source: "IMPORTED" }]));
  const rows = [];
  const anchor = new Date(`${todayISODate()}T12:00:00Z`);
  for (let offset = Math.max(1, Number(rangeDays || 84)) - 1; offset >= 0; offset -= 1) {
    const date = new Date(anchor.getTime() - offset * 86400000).toISOString().slice(0, 10);
    const manual = readManualNutrition(date);
    const record = importedByDate.get(date) || (manual ? { ...manual, source: "MANUAL" } : null);
    if (record) rows.push(record);
  }
  return rows;
}

function trendMetricValue(value, suffix = "") {
  if (value === null || value === undefined || !Number.isFinite(Number(value))) return "—";
  return `${value}${suffix}`;
}

function trendSeriesBars(series = [], options = {}) {
  const points = (series || []).filter((item) => Number.isFinite(Number(item.value))).slice(-12);
  if (!points.length) return '<div class="trend-chart-empty"><strong>Signal not established</strong><span>Keep logging to unlock this trajectory.</span></div>';
  const values = points.map((item) => Number(item.value));
  const fixedMin = Number.isFinite(Number(options.min)) ? Number(options.min) : null;
  const fixedMax = Number.isFinite(Number(options.max)) ? Number(options.max) : null;
  let min = fixedMin ?? Math.min(...values);
  let max = fixedMax ?? Math.max(...values);
  if (min === max) {
    min -= Math.max(1, Math.abs(min) * 0.04);
    max += Math.max(1, Math.abs(max) * 0.04);
  }
  const span = max - min || 1;
  const unit = options.unit || "";
  return `<div class="trend-bars" role="img" aria-label="${escapeHtml(options.label || "Trend")} from ${escapeHtml(points[0].date)} to ${escapeHtml(points.at(-1).date)}">
    ${points.map((item) => {
      const value = Number(item.value);
      const height = Math.max(8, Math.min(100, ((value - min) / span) * 88 + 8));
      return `<div class="trend-bar" style="--trend-bar:${height}%"><i></i><strong>${escapeHtml(Number.isInteger(value) ? value : value.toFixed(1))}${escapeHtml(unit)}</strong><span>${escapeHtml(item.date.slice(5))}</span></div>`;
    }).join("")}
  </div>`;
}

function trendSparkBars(series = []) {
  const points = (series || []).filter((item) => Number.isFinite(Number(item.value))).slice(-7);
  if (!points.length) return '<span class="trend-spark empty"></span>';
  const values = points.map((item) => Number(item.value));
  const min = Math.min(...values);
  const max = Math.max(...values);
  const span = max - min || 1;
  return `<span class="trend-spark" aria-hidden="true">${points.map((item) => `<i style="--spark:${Math.max(18, ((Number(item.value) - min) / span) * 82 + 18)}%"></i>`).join("")}</span>`;
}

function renderTrendPrimaryChart(model = trendDashboardModel) {
  const element = document.getElementById("trend-primary-chart");
  const title = document.getElementById("trend-focus-title");
  if (!element || !title || !model) return;
  const configs = {
    discipline: { title: "Discipline", series: model.discipline.series, unit: "%", min: 0, max: 100 },
    readiness: { title: "Readiness", series: model.readiness.series, unit: "", min: 1, max: 10 },
    weight: { title: "Weight", series: model.weight.series, unit: "", min: null, max: null }
  };
  const config = configs[trendActiveMetric] || configs.discipline;
  title.textContent = config.title;
  element.innerHTML = trendSeriesBars(config.series, { ...config, label: `${config.title} trajectory` });
  document.querySelectorAll("[data-trend-metric]").forEach((button) => button.setAttribute("aria-pressed", button.dataset.trendMetric === trendActiveMetric ? "true" : "false"));
}

function setTrendView(view = "overview") {
  trendActiveView = ["overview", "training", "recovery", "body"].includes(view) ? view : "overview";
  document.querySelectorAll("[data-trend-pane]").forEach((pane) => { pane.hidden = pane.dataset.trendPane !== trendActiveView; });
  document.querySelectorAll("[data-trend-view]").forEach((button) => button.setAttribute("aria-selected", button.dataset.trendView === trendActiveView ? "true" : "false"));
  saveTrendPreferences();
}

function buildCurrentBodyOutcomeModel(programModel = trendDashboardModel) {
  if (typeof DominionBodyComposition === "undefined") return null;
  return DominionBodyComposition.buildOutcomeModel({
    today: todayISODate(),
    rangeDays: trendRangeDays,
    performanceEntries,
    dailyStates: mergeReadinessHistory(),
    contract: readApprovedRecruitContract() || {},
    signals: {
      discipline: programModel?.discipline?.value,
      nutrition: programModel?.nutrition?.value,
      strengthSessions: programModel?.training?.strengthSessions || 0
    },
    priorReview: readBodyOutcomeReview()
  });
}

function buildCurrentProgressReview(outcome = buildCurrentBodyOutcomeModel(), programModel = trendDashboardModel) {
  if (!outcome || typeof DominionProgressReview === "undefined") return null;
  const latestWeek = addClosedLoopDays(todayISODate(), -6);
  const readinessPain = mergeReadinessHistory().some((item) => item.date >= latestWeek && item.date <= todayISODate() && Boolean(item.pain));
  const trends = programModel || {
    weight: { observations: outcome.weight?.observations || 0, change: outcome.weight?.change ?? null },
    nutrition: { evidenceDays: 0, value: null },
    training: { observations: 0, strengthSessions: 0, strengthDelta: 0, runSessions: 0, runDelta: null, totalSessionDays: 0 },
    readiness: { observations: 0, value: null },
    discipline: { observations: 0, value: null }
  };
  return DominionProgressReview.buildProgressReview({
    today: todayISODate(),
    contract: readApprovedRecruitContract() || {},
    bodyOutcome: outcome,
    trends,
    readinessPain,
    priorReview: readProgressReview(),
    generatedAt: new Date().toISOString()
  });
}

function planCommandCurrentPlans() {
  return {
    nutrition: typeof activeNutritionBaseline === "function" ? activeNutritionBaseline(todayISODate()) : null,
    strength: readApprovedStrengthPlan(),
    running: readApprovedRunningBlock(),
    core: readApprovedCorePlan()
  };
}

function planCommandPlansFor(command = {}, useProposed = true) {
  const plans = planCommandCurrentPlans();
  if (!useProposed || !command?.domain || !command.proposedPlan) return plans;
  const key = { NUTRITION: "nutrition", STRENGTH: "strength", RUNNING: "running", CORE: "core" }[command.domain];
  if (key) plans[key] = command.proposedPlan;
  return plans;
}

function planCommandCalendarPreview(command = {}, useProposed = true, weekStart = command.effectiveDate) {
  if (!weekStart || typeof DominionWeeklyOrchestrator === "undefined") return null;
  const plans = planCommandPlansFor(command, useProposed);
  const draft = DominionWeeklyOrchestrator.buildUnifiedWeek({
    contract: readApprovedRecruitContract(),
    strengthPlan: plans.strength,
    runningBlock: plans.running,
    corePlan: plans.core,
    nutritionBaseline: plans.nutrition
  }, {
    today: todayISODate(),
    weekStart,
    generatedAt: new Date().toISOString()
  });
  return applyContractActivationGuards(draft, weekStart);
}

function buildCurrentPlanCommand(review = readProgressReview()) {
  if (typeof DominionPlanCommand === "undefined") return null;
  const command = DominionPlanCommand.buildPlanCommand({
    today: todayISODate(),
    review: review || {},
    currentPlans: planCommandCurrentPlans(),
    priorCommand: readPlanCommand(),
    generatedAt: new Date().toISOString()
  });
  if (command.status !== "DRAFT") return command;
  const preview = planCommandCalendarPreview(command, true, command.effectiveDate);
  return preview ? DominionPlanCommand.withCalendarPreview(command, preview) : command;
}

function buildCurrentObservationVerdict(command = buildCurrentPlanCommand()) {
  if (typeof DominionObservationVerdict === "undefined") return null;
  const prior = readObservationVerdict();
  return DominionObservationVerdict.buildObservationVerdict({
    today: todayISODate(),
    command,
    priorVerdict: prior?.commandId === command?.id ? prior : null,
    dailyStates: mergeReadinessHistory(),
    nutritionDays: trendNutritionHistory(120),
    nutritionTargets: currentNutritionBaseTargets(todayISODate()),
    performanceEntries,
    strengthHistory: readStrengthHistory(),
    coreHistory: readCoreHistory(),
    generatedAt: new Date().toISOString()
  });
}

function observationVerdictTone(verdict = {}) {
  if (verdict.decision === "RETAIN" || verdict.recommendation === "RETAIN") return "positive";
  if (verdict.decision === "ROLLBACK" || verdict.recommendation === "ROLLBACK") return "danger";
  return "warning";
}

function observationVerdictMarkup(verdict = {}, compact = false) {
  if (!verdict?.id || verdict.status === "WAITING") return "";
  const tone = observationVerdictTone(verdict);
  const recommendation = verdict.decision || verdict.recommendation;
  if (compact) {
    if (verdict.status !== "READY") return "";
    return `<article class="observation-verdict-card compact ${tone}" data-observation-state="${escapeHtml(verdict.status)}">
      <header><span>ATLAS VERDICT · ${escapeHtml(verdict.domain)}</span><strong>${escapeHtml(verdict.confidence?.label || "LEARNING")} EVIDENCE</strong></header>
      <h3>${escapeHtml(recommendation === "RETAIN" ? "Keep the change" : recommendation === "ROLLBACK" ? "Restore the prior plan" : "Observe seven more days")}</h3>
      <p>${escapeHtml(verdict.rationale)}</p>
      <div class="observation-verdict-actions"><button type="button" data-observation-verdict-route="trends">Review evidence</button></div>
    </article>`;
  }
  const metrics = (verdict.metrics || []).map((item) => `<article>
    <span>${escapeHtml(item.label)}</span>
    <div><small>BEFORE</small><strong>${escapeHtml(item.baseline)}</strong></div>
    <i aria-hidden="true">→</i>
    <div><small>AFTER</small><strong>${escapeHtml(item.observed)}</strong></div>
  </article>`).join("");
  const requirements = (verdict.requirements || []).map((item) => `<li>${escapeHtml(item)}</li>`).join("");
  const title = verdict.status === "RESOLVED"
    ? `${verdict.decision === "RETAIN" ? "Change retained" : "Prior plan restored"}`
    : verdict.status === "EXTENDED"
      ? `Observation extended to ${verdict.nextObservationEnd}`
      : verdict.status === "READY"
        ? recommendation === "RETAIN" ? "Retain the change" : recommendation === "ROLLBACK" ? "Roll back the change" : "Observe seven more days"
        : verdict.status === "SCHEDULED" ? `Observation starts ${verdict.windows?.observationStart}` : `Observation in progress`;
  let actions = "";
  if (verdict.status === "READY") {
    actions = `<div class="observation-verdict-actions">
      <button type="button" data-observation-verdict-action="RETAIN">Retain change</button>
      <button type="button" class="ghost" data-observation-verdict-action="EXTEND" ${Number(verdict.extensionCount || 0) >= 2 ? "disabled" : ""}>Observe 7 more days</button>
      <button type="button" class="ghost danger" data-observation-verdict-action="ROLLBACK">Roll back</button>
    </div>`;
  }
  return `<article class="observation-verdict-card ${tone}" data-observation-state="${escapeHtml(verdict.status)}">
    <header><div><span>ATLAS OBSERVATION VERDICT · ${escapeHtml(verdict.domain)}</span><h3>${escapeHtml(title)}</h3></div><strong>${escapeHtml(verdict.confidence?.score ?? 0)}% ${escapeHtml(verdict.confidence?.label || "LEARNING")}</strong></header>
    <p>${escapeHtml(verdict.rationale || "Atlas is collecting the result of the approved change.")}</p>
    <div class="observation-verdict-window"><span>BEFORE · ${escapeHtml(verdict.windows?.baselineStart || "—")} TO ${escapeHtml(verdict.windows?.baselineEnd || "—")}</span><span>AFTER · ${escapeHtml(verdict.windows?.observationStart || "—")} TO ${escapeHtml(verdict.windows?.observedThrough || "—")}</span></div>
    <div class="observation-verdict-metrics">${metrics}</div>
    <div class="observation-verdict-evidence"><strong>Evidence check</strong><ul>${requirements}</ul></div>
    ${actions}
    <footer><small>${readObservationVerdictHistory().length} decision receipt${readObservationVerdictHistory().length === 1 ? "" : "s"}</small><small>No plan changes without your decision</small></footer>
  </article>`;
}

function renderObservationVerdict(targetId, compact = false) {
  const target = document.getElementById(targetId);
  if (!target) return;
  const verdict = buildCurrentObservationVerdict();
  target.innerHTML = verdict ? observationVerdictMarkup(verdict, compact) : "";
  target.hidden = !target.innerHTML;
}

function renderObservationVerdictSurfaces() {
  renderObservationVerdict("today-observation-verdict", true);
  renderObservationVerdict("body-observation-verdict");
}

function planCommandPlanSummary(domain, plan = {}) {
  if (domain === "NUTRITION") {
    const targets = plan.recoveryTargets || {};
    return `<strong>${Math.round(Number(targets.calories || 0))} kcal</strong><small>${Math.round(Number(targets.protein || 0))}g protein · ${Math.round(Number(targets.carbs || 0))}g carbs</small>`;
  }
  if (domain === "STRENGTH") {
    const sets = (plan.sessions || []).flatMap((item) => item.exercises || []).reduce((sum, item) => sum + Number(item.recommendedSets || 0), 0);
    return `<strong>${Number(plan.profile?.daysPerWeek || plan.sessions?.length || 0)} days</strong><small>${sets} work sets · revision ${Number(plan.revision || 1)}</small>`;
  }
  if (domain === "RUNNING") {
    const week = plan.weeks?.[0] || {};
    return `<strong>${Number(week.weeklyDistance || plan.baselineDistance || 0)} ${escapeHtml(plan.profile?.preferredUnit || "mi")}</strong><small>${Number(plan.profile?.runningDaysPerWeek || 0)} run days · block ${Number(plan.revision || 1)}</small>`;
  }
  if (domain === "CORE") {
    return `<strong>${Number(plan.profile?.sessionMinutes || 0)} min/session</strong><small>${Number(plan.profile?.sessionsPerWeek || 0)} sessions/week</small>`;
  }
  return "<strong>Current plan</strong>";
}

function planCommandStatusTone(status = "") {
  if (["SCHEDULED", "OBSERVING", "RETAINED"].includes(status)) return "positive";
  if (["DRAFT", "REVIEW_DUE"].includes(status)) return "warning";
  if (["BLOCKED", "ROLLED_BACK"].includes(status)) return "danger";
  return "neutral";
}

function planCommandMarkup(command = {}, compact = false) {
  if (!command?.id || command.status === "WAITING") return "";
  if (compact && ["HELD", "REJECTED", "RETAINED", "ROLLED_BACK"].includes(command.status)) return "";
  const tone = planCommandStatusTone(command.status);
  const domain = String(command.domain || "PLAN").toUpperCase();
  if (compact) {
    const action = ["DRAFT", "BLOCKED", "REVIEW_DUE"].includes(command.status)
      ? '<button type="button" data-plan-command-route="trends">Open plan decision</button>'
      : command.status === "OBSERVING"
        ? '<button type="button" class="ghost danger" data-plan-command-action="ROLLBACK">Roll back</button>'
        : "";
    return `<article class="plan-command-card compact ${tone}" data-plan-command-state="${escapeHtml(command.status)}">
      <header><span>${escapeHtml(domain)} PLAN</span><strong>${escapeHtml(command.status.replaceAll("_", " "))}</strong></header>
      <h3>${escapeHtml(command.headline)}</h3><p>${escapeHtml(command.detail)}</p>
      ${action ? `<div class="plan-command-actions">${action}</div>` : ""}
    </article>`;
  }
  const comparison = command.currentPlan && command.proposedPlan ? `<div class="plan-command-compare">
    <article><span>CURRENT</span>${planCommandPlanSummary(domain, command.currentPlan)}</article>
    <i aria-hidden="true">→</i>
    <article class="proposed"><span>PROPOSED</span>${planCommandPlanSummary(domain, command.proposedPlan)}</article>
  </div>` : "";
  const preview = command.calendarPreview || {};
  const blockers = (preview.conflicts || []).filter((item) => item.severity === "BLOCKING");
  const calendar = preview.weekStart ? `<div class="plan-command-calendar ${blockers.length ? "blocked" : "clear"}">
    <div><span>NEXT WEEK</span><strong>${escapeHtml(preview.weekStart)}</strong><small>${Number(preview.trainingDays || 0)} training days · ${Number(preview.recoveryDays || 0)} recovery</small></div>
    <div><span>CALENDAR</span><strong>${blockers.length ? `${blockers.length} blocker${blockers.length === 1 ? "" : "s"}` : "CLEAR"}</strong><small>${escapeHtml(command.change?.calendar || "No placement change")}</small></div>
  </div>` : "";
  const blockerList = blockers.length ? `<details class="plan-command-blockers" open><summary>Resolve before approval</summary><ul>${blockers.map((item) => `<li>${escapeHtml(item.detail || item.code)}</li>`).join("")}</ul></details>` : "";
  let actions = "";
  if (command.status === "DRAFT") {
    actions = `<div class="plan-command-actions"><button type="button" data-plan-command-action="APPROVE" ${command.approvalBlocked ? "disabled" : ""}>Approve for ${escapeHtml(command.effectiveDate)}</button><button type="button" class="ghost" data-plan-command-action="HOLD">Hold current plan</button><button type="button" class="ghost danger" data-plan-command-action="REJECT">Reject change</button></div>`;
  } else if (command.status === "SCHEDULED") {
    actions = `<div class="plan-command-actions"><button type="button" class="ghost danger" data-plan-command-action="ROLLBACK">Cancel scheduled change</button></div>`;
  } else if (command.status === "OBSERVING") {
    const total = 14;
    const elapsed = Math.max(1, Math.min(total, Math.round((new Date(`${todayISODate()}T12:00:00Z`) - new Date(`${command.effectiveDate}T12:00:00Z`)) / 86400000) + 1));
    actions = `<div class="plan-command-observation"><span>OBSERVATION</span><strong>Day ${elapsed} of ${total}</strong><i><b style="--plan-observation:${elapsed / total * 100}%"></b></i></div><div class="plan-command-actions"><button type="button" class="ghost danger" data-plan-command-action="ROLLBACK">Roll back now</button></div>`;
  } else if (command.status === "REVIEW_DUE") {
    actions = '<div class="plan-command-actions"><button type="button" data-plan-command-route="trends">Review Atlas verdict</button></div>';
  } else if (command.status === "BLOCKED") {
    actions = `<div class="plan-command-actions"><button type="button" data-plan-command-route="${domain === "NUTRITION" ? "nutrition" : "performance"}">Open ${escapeHtml(domain.toLowerCase())}</button></div>`;
  }
  return `<article class="plan-command-card ${tone}" data-plan-command-state="${escapeHtml(command.status)}">
    <header><div><span>ATLAS PLAN COMMAND · ${escapeHtml(domain)}</span><h3>${escapeHtml(command.headline)}</h3></div><strong>${escapeHtml(command.status.replaceAll("_", " "))}</strong></header>
    <p>${escapeHtml(command.detail)}</p>${comparison}
    ${command.change ? `<div class="plan-command-change"><span>ONE LEVER</span><strong>${escapeHtml(command.change.label)}</strong><small>Effective ${escapeHtml(command.effectiveDate || "after approval")}</small></div>` : ""}
    ${calendar}${blockerList}${actions}
    <footer><small>${readPlanCommandHistory().length} prior decision${readPlanCommandHistory().length === 1 ? "" : "s"}</small><small>Preview · approve · observe · retain or roll back</small></footer>
  </article>`;
}

function renderPlanCommand(targetId, compact = false) {
  const target = document.getElementById(targetId);
  if (!target) return;
  const command = buildCurrentPlanCommand();
  target.innerHTML = command ? planCommandMarkup(command, compact) : "";
  target.hidden = !target.innerHTML;
}

function planCommandNutritionInput(plan = {}, effectiveDate = plan.effectiveDate) {
  const recovery = plan.recoveryTargets || {};
  const adjustments = plan.trainingAdjustments || {};
  return {
    goal: plan.goal || "FAT_LOSS",
    effectiveDate,
    calories: recovery.calories,
    protein: recovery.protein,
    carbs: recovery.carbs,
    fat: recovery.fat,
    trainingCalories: Number(adjustments.calories || 0),
    trainingCarbs: Number(adjustments.carbs || 0)
  };
}

function preparePlanCommandNutritionBaseline(command = {}) {
  if (command.domain !== "NUTRITION") return null;
  if (typeof DominionNutritionBaseline === "undefined") throw new Error("Nutrition baseline controls are unavailable.");
  const proposal = DominionNutritionBaseline.buildNutritionBaselineProposal(planCommandNutritionInput(command.proposedPlan, command.effectiveDate));
  if (proposal.status !== "READY FOR APPROVAL") throw new Error(proposal.errors?.[0] || "The proposed Nutrition baseline did not pass its safeguards.");
  return DominionNutritionBaseline.approveNutritionBaseline(proposal, command.approvedAt || new Date().toISOString(), command.proposedPlan?.id || `plan-command-nutrition:${command.id}`);
}

async function persistPlanCommandNutritionBaseline(baseline = null) {
  if (!baseline?.id) return null;
  const history = readNutritionBaselineHistory();
  const next = [baseline, ...history.filter((item) => item.id !== baseline.id)];
  await persistOutcomeNutritionHistory(next);
  return baseline;
}

async function commitPlanCommandCalendar(command = {}, useProposed = true, weekStart = command.effectiveDate) {
  if (typeof DominionWeeklyOrchestrator === "undefined") throw new Error("Calendar coordination is unavailable.");
  const draft = planCommandCalendarPreview(command, useProposed, weekStart);
  if (!draft) throw new Error("The next operating week could not be built.");
  if (draft.approvalBlocked) throw new Error("Resolve the calendar blockers before approving this plan change.");
  const history = readUnifiedWeekHistory();
  const previous = history.find((item) => item.status !== "REPLACED" && item.weekStart === draft.weekStart) || null;
  const approved = DominionWeeklyOrchestrator.approveWeek(draft, previous, { approvedAt: new Date().toISOString() });
  const nextHistory = DominionWeeklyOrchestrator.mergeCommittedWeek(history, approved);
  const strengthSchedule = DominionWeeklyOrchestrator.strengthScheduleFromWeek(approved);
  saveWeeklyOrchestrationLocal("HISTORY", "current", nextHistory);
  saveWeeklyOrchestrationLocal("WEEK", approved.weekStart, approved);
  saveStrengthStateLocal("SCHEDULE", `unified-${approved.weekStart}`, strengthSchedule);
  await persistWeeklyOrchestrationState("WEEK", approved.weekStart, approved);
  await persistWeeklyOrchestrationState("HISTORY", "current", nextHistory);
  await persistStrengthTrainingState("SCHEDULE", `unified-${approved.weekStart}`, strengthSchedule);
  if (readUnifiedWeekDraft()?.weekStart === approved.weekStart) await clearWeeklyOrchestrationDraft();
  return approved;
}

async function stagePlanCommand(command = {}) {
  const nutritionBaseline = preparePlanCommandNutritionBaseline(command);
  const calendar = await commitPlanCommandCalendar(command, true, command.effectiveDate);
  if (nutritionBaseline) await persistPlanCommandNutritionBaseline(nutritionBaseline);
  return {
    ...command,
    scheduledPlanId: nutritionBaseline?.id || command.proposedPlan?.id || null,
    scheduledCalendarId: calendar?.id || null,
    calendarPreview: calendar || command.calendarPreview
  };
}

async function applyPlanCommandToModule(command = {}) {
  const plan = { ...(command.proposedPlan || {}), approvedAt: command.approvedAt || new Date().toISOString(), activatedAt: new Date().toISOString() };
  if (command.domain === "NUTRITION") {
    let baseline = readNutritionBaselineHistory().find((item) => item.id === command.scheduledPlanId || item.id === command.proposedPlan?.id) || null;
    if (!baseline) baseline = await persistPlanCommandNutritionBaseline(preparePlanCommandNutritionBaseline(command));
    return baseline?.id || null;
  }
  if (command.domain === "STRENGTH") {
    saveStrengthStateLocal("PLAN", "current", plan);
    await persistStrengthTrainingState("PLAN", "current", plan);
  } else if (command.domain === "RUNNING") {
    if (command.currentPlan?.id) await persistRunningState("PLAN", `archive:${command.currentPlan.id}`, command.currentPlan);
    saveRunningBlockLocal("active", plan);
    await persistRunningState("PLAN", "active", plan);
  } else if (command.domain === "CORE") {
    saveCoreProgramLocal("PLAN", "current", plan);
    saveCoreProgramLocal("DRAFT", "current", plan);
    await persistCoreProgramState("PLAN", "current", plan);
    await persistCoreProgramState("DRAFT", "current", plan);
  } else {
    throw new Error("That plan module is not available for activation.");
  }
  return plan.id || null;
}

async function restorePlanCommandModule(command = {}) {
  const plan = { ...(command.currentPlan || {}), restoredAt: new Date().toISOString(), restoredFromPlanCommandId: command.id };
  if (command.domain === "NUTRITION") {
    const history = readNutritionBaselineHistory();
    const scheduledId = command.scheduledPlanId || command.proposedPlan?.id;
    if (todayISODate() < command.effectiveDate) {
      const next = history.map((item) => item.id === scheduledId ? { ...item, status: "REVERTED", revertedAt: new Date().toISOString() } : item);
      await persistOutcomeNutritionHistory(next);
      return plan.id || null;
    }
    if (typeof DominionNutritionBaseline === "undefined") throw new Error("Nutrition baseline controls are unavailable.");
    const proposal = DominionNutritionBaseline.buildNutritionBaselineProposal(planCommandNutritionInput(plan, todayISODate()));
    if (proposal.status !== "READY FOR APPROVAL") throw new Error(proposal.errors?.[0] || "The prior Nutrition baseline could not be restored.");
    const rollback = DominionNutritionBaseline.approveNutritionBaseline(proposal, new Date().toISOString(), `rollback:${command.id}:${todayISODate()}`);
    await persistOutcomeNutritionHistory([rollback, ...history.filter((item) => item.id !== rollback.id)]);
    return rollback.id;
  }
  if (todayISODate() < command.effectiveDate) return plan.id || null;
  if (command.domain === "STRENGTH") {
    saveStrengthStateLocal("PLAN", "current", plan);
    await persistStrengthTrainingState("PLAN", "current", plan);
  } else if (command.domain === "RUNNING") {
    saveRunningBlockLocal("active", plan);
    await persistRunningState("PLAN", "active", plan);
  } else if (command.domain === "CORE") {
    saveCoreProgramLocal("PLAN", "current", plan);
    saveCoreProgramLocal("DRAFT", "current", plan);
    await persistCoreProgramState("PLAN", "current", plan);
    await persistCoreProgramState("DRAFT", "current", plan);
  }
  return plan.id || null;
}

async function rollbackPlanCommand(command = {}) {
  const planId = await restorePlanCommandModule(command);
  const rollbackWeek = todayISODate() < command.effectiveDate
    ? command.effectiveDate
    : (typeof DominionWeeklyOrchestrator === "undefined" ? command.effectiveDate : DominionWeeklyOrchestrator.weekStartIso(todayISODate()));
  const calendar = await commitPlanCommandCalendar(command, false, rollbackWeek);
  return DominionPlanCommand.completeObservation(command, "ROLLBACK", {
    closedAt: new Date().toISOString(),
    planId,
    calendarId: calendar?.id || null
  });
}

async function activateDuePlanCommand() {
  if (typeof DominionPlanCommand === "undefined") return null;
  let command = readPlanCommand();
  if (!command?.id) return null;
  const refreshed = DominionPlanCommand.refreshLifecycle(command, todayISODate());
  if (!refreshed) return null;
  if (refreshed.status === "SCHEDULED" && todayISODate() >= refreshed.effectiveDate && !refreshed.appliedAt) {
    const planId = await applyPlanCommandToModule(refreshed);
    command = DominionPlanCommand.markApplied(refreshed, {
      appliedAt: new Date().toISOString(),
      planId,
      calendarId: refreshed.scheduledCalendarId || refreshed.calendarPreview?.id || null
    });
    await savePlanCommand(command);
    return command;
  }
  if (refreshed.status !== command.status) {
    await savePlanCommand(refreshed);
    return refreshed;
  }
  return refreshed;
}

function renderPlanCommandSurfaces() {
  renderPlanCommand("today-plan-command", true);
  renderPlanCommand("body-plan-command");
  renderObservationVerdictSurfaces();
  renderWeeklyOrchestrator();
  renderTodayCommittedWeek();
  renderTodayCommandSurface();
  renderDailyAssignment();
  renderNutritionCommand();
  renderPerformanceSection();
}

async function handleObservationVerdictAction(event) {
  const route = event.target.closest("button[data-observation-verdict-route]");
  if (route) {
    setActiveSection("trends");
    setTrendView("body");
    window.history.replaceState(null, "", "#trends");
    document.getElementById("body-observation-verdict")?.scrollIntoView({ behavior: "smooth", block: "start" });
    return true;
  }
  const button = event.target.closest("button[data-observation-verdict-action]");
  if (!button || typeof DominionObservationVerdict === "undefined" || typeof DominionPlanCommand === "undefined") return false;
  button.disabled = true;
  try {
    const action = button.dataset.observationVerdictAction;
    let command = buildCurrentPlanCommand();
    const verdict = buildCurrentObservationVerdict(command);
    if (!command?.id || !verdict?.id) throw new Error("No observation verdict is ready.");
    const receipt = DominionObservationVerdict.resolveVerdict(verdict, action, {
      decidedAt: new Date().toISOString(),
      userId: session?.user?.id || null
    });
    if (action === "EXTEND") {
      command = {
        ...command,
        status: "OBSERVING",
        observationEnd: receipt.nextObservationEnd,
        extensionCount: receipt.extensionCount,
        extendedAt: receipt.decidedAt,
        lastObservationDecision: "EXTEND"
      };
    } else if (action === "RETAIN") {
      command = DominionPlanCommand.completeObservation(command, "RETAIN", { closedAt: receipt.decidedAt });
    } else {
      command = await rollbackPlanCommand(command);
    }
    const [commandSynced, verdictSynced] = await Promise.all([savePlanCommand(command), saveObservationVerdict(receipt)]);
    renderPlanCommandSurfaces();
    if (trendAnalyticsContext) renderTrendsAnalytics(trendAnalyticsContext.inspections, trendAnalyticsContext.dailyRecords, trendAnalyticsContext.storageMode);
    const message = action === "EXTEND"
      ? `Observation extended through ${receipt.nextObservationEnd}. The approved change remains active.`
      : action === "RETAIN"
        ? "Verdict recorded. The observed change is now the retained plan."
        : "Verdict recorded. The prior plan and calendar were restored.";
    const syncNote = commandSynced && verdictSynced ? " Saved to your account." : " Saved on this device; account sync will retry.";
    setText("observation-verdict-feedback", `${message}${syncNote}`);
    setText("plan-command-feedback", `${message}${syncNote}`);
  } catch (error) {
    setText("observation-verdict-feedback", error?.message || "That observation decision could not be completed.");
  } finally {
    button.disabled = false;
  }
  return true;
}

async function handlePlanCommandAction(event) {
  const routeButton = event.target.closest("button[data-plan-command-route]");
  if (routeButton) {
    const route = routeButton.dataset.planCommandRoute;
    if (route === "trends") {
      setActiveSection("trends");
      setTrendView("body");
      window.history.replaceState(null, "", "#trends");
    } else if (route === "nutrition") {
      setActiveSection("nutrition");
      window.history.replaceState(null, "", "#nutrition");
    } else {
      setActiveSection("performance");
      const domain = String(buildCurrentPlanCommand()?.domain || "STRENGTH").toLowerCase();
      setPerformanceActiveView(domain === "running" ? "running" : domain === "core" ? "core" : "today_training");
      window.history.replaceState(null, "", "#performance");
    }
    return true;
  }
  const button = event.target.closest("button[data-plan-command-action]");
  if (!button || typeof DominionPlanCommand === "undefined") return false;
  button.disabled = true;
  try {
    const action = button.dataset.planCommandAction;
    let command = buildCurrentPlanCommand();
    if (!command?.id) throw new Error("No plan decision is ready.");
    if (["APPROVE", "HOLD", "REJECT"].includes(action)) {
      command = DominionPlanCommand.resolvePlanCommand(command, action, { resolvedAt: new Date().toISOString(), userId: session?.user?.id || null });
      if (action === "APPROVE") command = await stagePlanCommand(command);
    } else if (action === "RETAIN") {
      command = DominionPlanCommand.completeObservation(command, "RETAIN", { closedAt: new Date().toISOString() });
    } else if (action === "ROLLBACK") {
      command = await rollbackPlanCommand(command);
    }
    const synced = await savePlanCommand(command);
    renderPlanCommandSurfaces();
    const message = command.status === "SCHEDULED"
      ? `Plan and calendar approved for ${command.effectiveDate}${synced ? " and saved to your account" : " on this device"}. The current plan remains active until then.`
      : command.status === "ROLLED_BACK"
        ? "The prior plan and calendar were restored. The decision remains in history."
        : command.status === "RETAINED"
          ? "The observed change is now the retained plan."
          : "Decision saved. No unapproved plan change was made.";
    setText("plan-command-feedback", message);
    setText("body-checkin-feedback", message);
    setText("today-body-checkin-feedback", message);
  } catch (error) {
    setText("plan-command-feedback", error?.message || "That plan decision could not be completed.");
    setText("body-checkin-feedback", error?.message || "That plan decision could not be completed.");
  } finally {
    button.disabled = false;
  }
  return true;
}

function progressReviewTone(review = {}) {
  if (review.classification === "ADVANCING" || review.status === "CONFIRMED") return "positive";
  if (review.classification === "REGRESSING" || review.status === "READY") return "warning";
  return "neutral";
}

function progressReviewMarkup(review = {}, compact = false) {
  const count = Math.min(Number(review.cycleTarget || 4), Number(review.cycleCount || 0));
  const progress = Math.min(100, count / Number(review.cycleTarget || 4) * 100);
  if (["BUILDING", "MONITORING"].includes(review.status)) {
    return `<article class="progress-review-card neutral ${compact ? "compact" : ""}" data-progress-review-state="${escapeHtml(review.status)}">
      <header><div><span>${escapeHtml(review.label || "NEXT REVIEW")}</span><h3>${escapeHtml(review.headline || "Build the signal")}</h3></div><strong>${count}/4</strong></header>
      <p>${escapeHtml(review.detail || "Four comparable checkpoints unlock the review.")}</p>
      <div class="progress-review-bar" aria-label="${count} of 4 checkpoints"><span style="--progress-review:${progress}%"></span></div>
      <footer><small>Next checkpoint ${escapeHtml(review.nextCheckInDate || "today")}</small><small>No plan changes</small></footer>
    </article>`;
  }
  const recommendation = review.recommendation || {};
  const signals = (review.signal?.signals || []).slice(0, compact ? 3 : 6);
  const signalMarkup = signals.length ? `<div class="progress-review-signals">${signals.map((item) => `<div><span>${escapeHtml(item.label)}</span><strong>${escapeHtml(item.value)}</strong></div>`).join("")}</div>` : "";
  const checks = (review.evidence?.checks || []).map((item) => `<li class="${item.pass ? "pass" : "hold"}"><span>${item.pass ? "✓" : "—"}</span>${escapeHtml(item.label)}</li>`).join("");
  const evidence = compact || !checks ? "" : `<details class="progress-review-evidence"><summary>Evidence ${Number(review.evidence?.score || 0)}% · ${escapeHtml(review.evidence?.label || "LEARNING")}</summary><ul>${checks}</ul></details>`;
  let actions = "";
  if (review.status === "READY") {
    actions = compact
      ? '<div class="progress-review-actions"><button type="button" data-progress-review-route="trends">Review the coaching call</button></div>'
      : `<div class="progress-review-actions"><button type="button" data-progress-review-action="ACCEPT">${escapeHtml(recommendation.label || "Accept recommendation")}</button><button type="button" class="ghost" data-progress-review-action="HOLD">Keep current plan</button><button type="button" class="ghost" data-progress-review-action="REASSESS_LATER">Reassess in 7 days</button></div>`;
  } else if (review.status === "DEFERRED") {
    actions = `<p class="progress-review-guardrail">Reopens ${escapeHtml(review.reassessDate || "after the next checkpoint")}.</p>`;
  } else if (review.status === "CONFIRMED" && recommendation.requiresPlanApproval) {
    actions = `<div class="progress-review-actions"><button type="button" data-progress-review-route="${escapeHtml(recommendation.section || "trends")}">Open ${escapeHtml(recommendation.domain || "plan")} decision</button></div>`;
  } else if (["CONFIRMED", "HELD"].includes(review.status)) {
    actions = `<p class="progress-review-guardrail">Decision recorded. The approved Contract and plans remain authoritative.</p>`;
  }
  return `<article class="progress-review-card ${progressReviewTone(review)} ${compact ? "compact" : ""}" data-progress-review-state="${escapeHtml(review.status || "READY")}">
    <header><div><span>ATLAS PROGRESS REVIEW</span><h3>${escapeHtml(review.headline || "Progress review")}</h3></div><strong>${escapeHtml(review.status === "READY" ? review.classification : review.status)}</strong></header>
    <div class="progress-review-call"><span>ONE COACHING CALL</span><h4>${escapeHtml(recommendation.headline || review.detail || "Hold the approved plan")}</h4><p>${escapeHtml(recommendation.detail || review.detail || "Atlas is monitoring the next evidence window.")}</p></div>
    ${signalMarkup}${evidence}${actions}
    <footer><small>${escapeHtml(review.sourceFirstDate || "—")} → ${escapeHtml(review.sourceLatestDate || "—")}</small><small>${readProgressReviewHistory().length} prior decision${readProgressReviewHistory().length === 1 ? "" : "s"} · No silent changes</small></footer>
  </article>`;
}

function renderProgressReview(outcome, targetId, compact = false) {
  const target = document.getElementById(targetId);
  if (!target || !outcome || typeof DominionProgressReview === "undefined") return;
  const review = buildCurrentProgressReview(outcome);
  if (!review) return;
  target.innerHTML = progressReviewMarkup(review, compact);
}

async function resolveProgressReviewAction(action) {
  if (typeof DominionProgressReview === "undefined") return false;
  const outcome = buildCurrentBodyOutcomeModel();
  const current = buildCurrentProgressReview(outcome);
  if (!current || current.status !== "READY") return false;
  const record = DominionProgressReview.resolveProgressReview(current, action, {
    resolvedAt: new Date().toISOString(),
    userId: session?.user?.id || null
  });
  if (action === "ACCEPT" && current.recommendation?.requiresPlanApproval && outcome?.review?.status === "PROPOSED" && typeof DominionBodyComposition !== "undefined") {
    const authorized = DominionBodyComposition.resolveOutcomeReview(outcome.review, "AUTHORIZE_REVIEW", {
      resolvedAt: new Date().toISOString(),
      userId: session?.user?.id || null
    });
    await saveBodyOutcomeReview(authorized);
  }
  const synced = await saveProgressReview(record);
  const nextOutcome = buildCurrentBodyOutcomeModel();
  renderTodayBodyCheckpoint(nextOutcome);
  renderBodyOutcome(nextOutcome);
  const message = action === "ACCEPT" && current.recommendation?.requiresPlanApproval
    ? `Review authorized${synced ? " and saved to your account" : " on this device"}. No plan changed; the separate plan decision is ready below.`
    : action === "ACCEPT"
      ? `Recommendation confirmed${synced ? " and saved to your account" : " on this device"}. The approved plan remains active.`
      : action === "REASSESS_LATER"
        ? "Review deferred for seven days. No plan changed."
        : "Current plan held. Atlas will start the next evidence cycle.";
  setText("body-checkin-feedback", message);
  setText("today-body-checkin-feedback", message);
  return true;
}

async function handleProgressReviewAction(event) {
  const actionButton = event.target.closest("button[data-progress-review-action]");
  if (actionButton) {
    actionButton.disabled = true;
    try { await resolveProgressReviewAction(actionButton.dataset.progressReviewAction); }
    catch (error) { setText("body-checkin-feedback", error?.message || "That progress decision could not be saved."); }
    finally { actionButton.disabled = false; }
    return true;
  }
  const routeButton = event.target.closest("button[data-progress-review-route]");
  if (routeButton) {
    const section = routeButton.dataset.progressReviewRoute || "trends";
    if (section === "trends") setTrendView("body");
    if (section === "performance" && readProgressReview()?.recommendation?.domain === "RUNNING") setPerformanceActiveView("running");
    setActiveSection(section);
    window.history.replaceState(null, "", `#${section}`);
    return true;
  }
  return false;
}

function renderBodyMeasurementChart(outcome) {
  const chart = document.getElementById("body-measurement-chart");
  const title = document.getElementById("body-measurement-title");
  if (!chart || !title || !outcome) return;
  const metric = outcome.measurements.summaries[trendBodyMetric] || outcome.measurements.summaries.waist;
  title.textContent = metric.label;
  const unit = metric.key === "body_fat" ? "%" : " in";
  chart.innerHTML = trendSeriesBars(metric.series, { label: `${metric.label} trajectory`, unit });
  document.querySelectorAll("[data-body-metric]").forEach((button) => button.setAttribute("aria-pressed", button.dataset.bodyMetric === metric.key ? "true" : "false"));
}

function renderBodyCheckInHistory(outcome) {
  const history = document.getElementById("body-checkin-history");
  if (!history || !outcome) return;
  const rows = [...outcome.measurements.checkIns].sort((a, b) => b.date.localeCompare(a.date)).slice(0, 8);
  history.innerHTML = rows.length ? rows.map((entry) => {
    const values = DominionBodyComposition.METRICS.filter((metric) => Object.hasOwn(entry.values, metric.key)).map((metric) => {
      const unit = metric.key === "body_fat" ? "%" : " in";
      const estimated = metric.key === "body_fat" && entry.bodyFatEstimate?.estimated ? " est." : "";
      return `${metric.label} ${Number(entry.values[metric.key]).toFixed(1).replace(/\.0$/, "")}${unit}${estimated}`;
    });
    return `<article data-body-entry-id="${escapeHtml(entry.id || "")}"><div><strong>${escapeHtml(entry.date)}</strong><span>${escapeHtml(values.join(" · "))}</span></div><div><button type="button" class="ghost" data-body-checkin-edit="${escapeHtml(entry.id || "")}">Edit</button><button type="button" class="ghost danger" data-body-checkin-delete="${escapeHtml(entry.id || "")}">Delete</button></div></article>`;
  }).join("") : '<div class="trend-chart-empty"><strong>No checkpoints yet</strong><span>Record one comparable weekly measurement set.</span></div>';
}

function bodyOutcomeReviewMarkup(review = {}, compact = false) {
  const tone = review.status === "AUTHORIZED" || review.status === "CURRENT"
    ? "positive"
    : review.status === "PROPOSED" ? "warning" : "neutral";
  let actions = "";
  if (review.status === "PROPOSED") {
    actions = `<div class="body-review-actions"><button type="button" data-body-review-action="AUTHORIZE_REVIEW">Authorize review</button><button type="button" class="ghost" data-body-review-action="KEEP_CURRENT">Keep current plan</button></div>`;
  } else if (review.status === "AUTHORIZED") {
    const label = review.nextSection === "trends" ? "Open plan review" : review.nextSection === "nutrition" ? "Open Fuel review" : "Open Training review";
    actions = `<div class="body-review-actions"><button type="button" data-body-review-route="${escapeHtml(review.nextSection || "trends")}">${label}</button></div>`;
  }
  const progress = review.status === "BUILDING"
    ? `<div class="body-review-progress" aria-label="${Number(review.checkpoints || 0)} of 4 checkpoints"><span style="--body-review-progress:${Math.min(100, Number(review.checkpoints || 0) / 4 * 100)}%"></span></div>`
    : "";
  return `<article class="body-review-card ${tone} ${compact ? "compact" : ""}">
    <header><div><span>FOUR-WEEK REVIEW</span><h3>${escapeHtml(review.headline || "Building the outcome signal")}</h3></div><strong>${escapeHtml(review.label || "BUILDING")}</strong></header>
    <p>${escapeHtml(review.detail || "Four comparable weekly checkpoints unlock the first review.")}</p>
    ${progress}
    <footer><small>${Number(review.checkpoints || 0)} checkpoint${Number(review.checkpoints || 0) === 1 ? "" : "s"} · ${Number(review.elapsedDays || 0)} days</small><small>No silent plan changes</small></footer>
    ${actions}
  </article>`;
}

function renderBodyOutcomeReview(outcome, targetId, compact = false) {
  const target = document.getElementById(targetId);
  if (!target || !outcome?.review) return;
  target.innerHTML = bodyOutcomeReviewMarkup(outcome.review, compact);
}

function outcomePlanReadiness() {
  const cutoff = addClosedLoopDays(todayISODate(), -6);
  const rows = mergeReadinessHistory().filter((item) => item.date >= cutoff && item.date <= todayISODate());
  const energy = rows.map((item) => Number(item.energy)).filter(Number.isFinite);
  return {
    value: trendDashboardModel?.readiness?.value ?? (energy.length ? energy.reduce((sum, value) => sum + value, 0) / energy.length : null),
    pain: rows.some((item) => Boolean(item.pain))
  };
}

function buildCurrentOutcomePlanRevision(outcome = buildCurrentBodyOutcomeModel()) {
  if (!outcome || typeof DominionOutcomePlanRevision === "undefined") return null;
  return DominionOutcomePlanRevision.buildProposal({
    today: todayISODate(),
    outcome,
    outcomeReview: outcome.review,
    contract: readApprovedRecruitContract() || {},
    nutritionBaseline: activeNutritionBaseline(todayISODate()),
    readiness: outcomePlanReadiness(),
    priorRevision: readOutcomePlanRevision(),
    generatedAt: new Date().toISOString()
  });
}

function outcomePlanTargetCards(plan = {}) {
  const recovery = plan.recoveryTargets || {};
  const training = plan.trainingTargets || {};
  return `<div class="outcome-plan-targets">
    <div><span>Recovery</span><strong>${Math.round(Number(recovery.calories || 0))} kcal</strong><small>${Math.round(Number(recovery.protein || 0))}g protein</small></div>
    <div><span>Training</span><strong>${Math.round(Number(training.calories || 0))} kcal</strong><small>${Math.round(Number(training.protein || 0))}g protein</small></div>
  </div>`;
}

function renderOutcomePlanRevision(outcome = buildCurrentBodyOutcomeModel()) {
  const output = document.getElementById("outcome-plan-revision-output");
  const state = document.getElementById("outcome-plan-revision-state");
  if (!output || !state || typeof DominionOutcomePlanRevision === "undefined") return;
  const revision = buildCurrentOutcomePlanRevision(outcome);
  if (!revision) return;
  state.textContent = revision.status.replaceAll("_", " ");
  state.className = ["SCHEDULED", "OBSERVING", "RETAINED"].includes(revision.status) ? "positive" : ["DRAFT", "REVIEW_DUE"].includes(revision.status) ? "warning" : "neutral";
  const checks = (revision.investigation?.checks || []).map((item) => `<li class="${item.pass ? "pass" : "hold"}"><span>${item.pass ? "✓" : "—"}</span><strong>${escapeHtml(item.label)}</strong></li>`).join("");
  const investigation = checks ? `<details class="outcome-plan-investigation" ${revision.status === "HOLD" ? "open" : ""}><summary>Investigation gate</summary><ul>${checks}</ul></details>` : "";
  let body = `<div class="outcome-plan-message"><span>${escapeHtml(revision.label || revision.status)}</span><h4>${escapeHtml(revision.headline || "Outcome review")}</h4><p>${escapeHtml(revision.detail || "Atlas is reconciling the outcome signal.")}</p></div>`;
  let actions = "";
  if (revision.status === "DRAFT") {
    body += `<div class="outcome-plan-compare">
      <article><header><span>CURRENT</span><strong>Approved Nutrition</strong></header>${outcomePlanTargetCards(revision.currentPlan)}</article>
      <i aria-hidden="true">→</i>
      <article class="proposed"><header><span>PROPOSED</span><strong>One lever · ${revision.proposedPlan.change.caloriePercent}% energy</strong></header>${outcomePlanTargetCards(revision.proposedPlan)}<small>Protein unchanged · Training unchanged</small></article>
    </div>
    <ul class="outcome-plan-rationale">${(revision.rationale || []).map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>
    <div class="outcome-plan-window"><div><span>Effective</span><strong>${escapeHtml(revision.effectiveDate)}</strong></div><div><span>Observe through</span><strong>${escapeHtml(revision.observationEnd)}</strong></div></div>`;
    actions = `<div class="outcome-plan-actions"><button type="button" data-outcome-plan-action="APPROVE">Approve for next week</button><button type="button" class="ghost" data-outcome-plan-action="KEEP_CURRENT">Keep current plan</button><button type="button" class="ghost" data-outcome-plan-action="REASSESS_LATER">Reassess in 7 days</button></div>`;
  } else if (revision.status === "SCHEDULED") {
    body += `<div class="outcome-plan-window"><div><span>Activates</span><strong>${escapeHtml(revision.effectiveDate)}</strong></div><div><span>Observation ends</span><strong>${escapeHtml(revision.observationEnd)}</strong></div></div><p class="outcome-plan-guardrail">The current baseline remains active until the effective date.</p>`;
    actions = '<div class="outcome-plan-actions"><button type="button" class="ghost danger" data-outcome-plan-action="ROLLBACK">Cancel scheduled revision</button></div>';
  } else if (revision.status === "OBSERVING") {
    const total = Math.max(1, Math.round((new Date(`${revision.observationEnd}T12:00:00Z`) - new Date(`${revision.effectiveDate}T12:00:00Z`)) / 86400000) + 1);
    const elapsed = Math.max(1, Math.min(total, Math.round((new Date(`${todayISODate()}T12:00:00Z`) - new Date(`${revision.effectiveDate}T12:00:00Z`)) / 86400000) + 1));
    body += `<div class="outcome-plan-observation"><div><span>OBSERVATION</span><strong>Day ${elapsed} of ${total}</strong></div><div class="outcome-plan-progress"><span style="--outcome-progress:${elapsed / total * 100}%"></span></div><small>Hold every other plan lever steady through ${escapeHtml(revision.observationEnd)}.</small></div>`;
    actions = '<div class="outcome-plan-actions"><button type="button" class="ghost danger" data-outcome-plan-action="ROLLBACK">Roll back now</button></div>';
  } else if (revision.status === "REVIEW_DUE") {
    body += `<p class="outcome-plan-guardrail">The 14-day observation window is complete. Retain the revision only if the outcome and recovery record support it.</p>`;
    actions = '<div class="outcome-plan-actions"><button type="button" data-outcome-plan-action="RETAIN">Retain revision</button><button type="button" class="ghost danger" data-outcome-plan-action="ROLLBACK">Roll back</button></div>';
  } else if (revision.status === "DEFERRED") {
    body += `<p class="outcome-plan-guardrail">Atlas will reopen this review on ${escapeHtml(revision.reassessDate || "the next checkpoint")}.</p>`;
  } else if (revision.status === "HELD") {
    body += '<p class="outcome-plan-guardrail">The current Nutrition and training plans remain authoritative.</p>';
  } else if (revision.status === "RETAINED") {
    body += '<p class="outcome-plan-guardrail">The observed revision remains the approved Nutrition baseline. The decision is preserved in history.</p>';
  } else if (revision.status === "REVERTED") {
    body += '<p class="outcome-plan-guardrail">The prior baseline was restored and the revision remains in the audit history.</p>';
  }
  output.innerHTML = `${body}${investigation}${actions}<footer>${readOutcomePlanRevisionHistory().length} prior decision${readOutcomePlanRevisionHistory().length === 1 ? "" : "s"} · One lever at a time</footer>`;
}

function outcomeNutritionBaselineInput(plan = {}, effectiveDate) {
  const recovery = plan.recoveryTargets || {};
  const adjustments = plan.trainingAdjustments || {};
  return {
    goal: plan.goal || "FAT_LOSS",
    effectiveDate,
    calories: recovery.calories,
    protein: recovery.protein,
    carbs: recovery.carbs,
    fat: recovery.fat,
    trainingCalories: Number(adjustments.calories || 0),
    trainingCarbs: Number(adjustments.carbs || 0)
  };
}

async function persistOutcomeNutritionHistory(history) {
  window.localStorage.setItem(nutritionBaselineStorageKey(), JSON.stringify(history));
  const synced = await persistNutritionState("BASELINE_HISTORY", "current", { items: history });
  ["MAINTAIN", "PERFORMANCE", "FAT_LOSS"].forEach((goalName) => window.localStorage.removeItem(adaptiveFuelingStorageKey(goalName)));
  await clearNutritionStateType("ADAPTIVE_APPROVAL");
  await refreshUnifiedWeekDraftForNutrition();
  renderNutritionCommand();
  renderRecruitContract();
  renderWeeklyOrchestrator();
  return synced;
}

function approveOutcomeNutritionBaseline(revision) {
  if (typeof DominionNutritionBaseline === "undefined") throw new Error("Nutrition baseline controls are unavailable.");
  const proposal = DominionNutritionBaseline.buildNutritionBaselineProposal(outcomeNutritionBaselineInput(revision.proposedPlan, revision.effectiveDate));
  if (proposal.status !== "READY FOR APPROVAL") throw new Error(proposal.errors?.[0] || "The proposed baseline did not pass Nutrition safeguards.");
  return DominionNutritionBaseline.approveNutritionBaseline(proposal, new Date().toISOString(), `outcome-${revision.id}`);
}

async function rollbackOutcomePlanRevision(revision) {
  if (typeof DominionNutritionBaseline === "undefined") throw new Error("Nutrition baseline controls are unavailable.");
  const history = readNutritionBaselineHistory();
  let rollbackBaselineId = null;
  if (todayISODate() < revision.effectiveDate) {
    const scheduled = history.find((item) => item.id === revision.appliedBaselineId);
    if (scheduled) scheduled.status = "REVERTED";
  } else {
    const proposal = DominionNutritionBaseline.buildNutritionBaselineProposal(outcomeNutritionBaselineInput(revision.currentPlan, todayISODate()));
    if (proposal.status !== "READY FOR APPROVAL") throw new Error(proposal.errors?.[0] || "The prior baseline could not be restored.");
    const rollback = DominionNutritionBaseline.approveNutritionBaseline(proposal, new Date().toISOString(), `rollback-${revision.id}-${todayISODate()}`);
    rollbackBaselineId = rollback.id;
    history.push(rollback);
  }
  await persistOutcomeNutritionHistory(history);
  return DominionOutcomePlanRevision.completeObservation(revision, "ROLLBACK", { closedAt: new Date().toISOString(), rollbackBaselineId });
}

async function handleOutcomePlanAction(event) {
  const button = event.target.closest("button[data-outcome-plan-action]");
  if (!button || typeof DominionOutcomePlanRevision === "undefined") return false;
  button.disabled = true;
  try {
    const action = button.dataset.outcomePlanAction;
    const outcome = buildCurrentBodyOutcomeModel();
    let revision = buildCurrentOutcomePlanRevision(outcome);
    let synced = false;
    if (["APPROVE", "KEEP_CURRENT", "REASSESS_LATER"].includes(action)) {
      revision = DominionOutcomePlanRevision.resolveProposal(revision, action, { resolvedAt: new Date().toISOString(), userId: session?.user?.id || null });
      if (action === "APPROVE") {
        const baseline = approveOutcomeNutritionBaseline(revision);
        const history = readNutritionBaselineHistory();
        if (!history.some((item) => item.id === baseline.id)) history.push(baseline);
        synced = await persistOutcomeNutritionHistory(history);
        revision = { ...revision, appliedBaselineId: baseline.id };
      }
    } else if (action === "RETAIN") {
      revision = DominionOutcomePlanRevision.completeObservation(revision, "RETAIN", { closedAt: new Date().toISOString() });
    } else if (action === "ROLLBACK") {
      revision = await rollbackOutcomePlanRevision(revision);
    }
    synced = (await saveOutcomePlanRevision(revision)) || synced;
    renderOutcomePlanRevision(outcome);
    setText("outcome-plan-revision-feedback", revision.status === "SCHEDULED"
      ? `Revision approved for ${revision.effectiveDate}${synced ? " and saved to your account" : " on this device"}. The current plan remains active until then.`
      : revision.status === "REVERTED"
        ? "Prior Nutrition baseline restored. Training was not changed."
        : revision.status === "RETAINED"
          ? "Revision retained after the observation window."
          : "Decision saved. No unapproved plan change was made.");
  } catch (error) {
    setText("outcome-plan-revision-feedback", error?.message || "That plan decision could not be completed.");
  } finally {
    button.disabled = false;
  }
  return true;
}

function renderTodayBodyCheckpoint(outcome = buildCurrentBodyOutcomeModel()) {
  const card = document.getElementById("today-body-checkpoint");
  if (!card || !outcome) return;
  const cadence = outcome.cadence || {};
  card.dataset.checkpointState = cadence.status || "UPCOMING";
  setText("today-body-checkpoint-state", cadence.label || "CHECKING");
  const state = document.getElementById("today-body-checkpoint-state");
  if (state) state.className = `state-pill ${cadence.status === "CAPTURED" ? "green" : cadence.status === "DUE" ? "yellow" : "neutral"}`;
  setText("today-body-checkpoint-detail", cadence.status === "CAPTURED"
    ? "Checkpoint secured. Atlas is updating the outcome signal."
    : cadence.status === "DUE"
      ? "Capture one comparable measurement set. Missing it never counts as noncompliance."
      : `Your next checkpoint is ${cadence.nextDate}.`);
  setText("today-body-checkpoint-last", cadence.latestDate || "No baseline");
  setText("today-body-checkpoint-next", cadence.status === "DUE" ? "Today" : cadence.nextDate || "Today");
  setText("today-body-capture-label", cadence.status === "CAPTURED" ? "Checkpoint captured" : cadence.status === "DUE" ? "Log weekly measurements" : "Log early if needed");
  const capture = document.getElementById("today-body-capture");
  if (capture && !capture.dataset.userToggled) capture.open = cadence.status === "DUE";
  const date = document.getElementById("today-body-checkin-date");
  if (date) date.value = todayISODate();
  renderBodyFatEstimate(document.getElementById("today-body-checkin-form"));
  renderBodyPhotoExperience();
  renderProgressReview(outcome, "today-body-review", true);
  renderPlanCommand("today-plan-command", true);
  renderObservationVerdict("today-observation-verdict", true);
}

function renderBodyOutcome(outcome) {
  if (!outcome) return;
  setText("body-outcome-decision", outcome.decision.label);
  const decision = document.getElementById("body-outcome-decision");
  if (decision) decision.className = outcome.decision.tone || "neutral";
  setText("body-outcome-headline", outcome.decision.headline);
  setText("body-outcome-detail", outcome.decision.detail);
  setText("body-outcome-confidence", `${outcome.confidence}%`);
  setText("body-outcome-confidence-label", outcome.confidenceLabel);
  setText("trend-body-weight", trendMetricValue(outcome.weight.latest, " lb"));
  setText("trend-body-change", outcome.weight.changeLabel);
  setText("trend-body-average", `7-day average ${trendMetricValue(outcome.weight.sevenDayAverage, " lb")}`);
  const chart = document.getElementById("trend-body-chart");
  if (chart) chart.innerHTML = trendSeriesBars(outcome.weight.series, { label: "Weight trajectory" });
  const dueLabel = outcome.nextCheckInDate <= todayISODate() ? "Due today" : `Next ${outcome.nextCheckInDate}`;
  setText("body-next-checkin", dueLabel);
  const grid = document.getElementById("body-measurement-grid");
  if (grid) grid.innerHTML = DominionBodyComposition.METRICS.map((definition) => {
    const metric = outcome.measurements.summaries[definition.key];
    const unit = definition.key === "body_fat" ? "%" : " in";
    const change = metric.change === null ? "Baseline needed" : `${metric.change > 0 ? "+" : metric.change < 0 ? "−" : ""}${Math.abs(metric.change)}${unit}`;
    const latestEntry = definition.key === "body_fat"
      ? [...outcome.measurements.checkIns].reverse().find((entry) => Object.hasOwn(entry.values, "body_fat"))
      : null;
    const estimateNote = latestEntry?.bodyFatEstimate?.estimated
      ? `<em>Estimated range ${escapeHtml(latestEntry.bodyFatEstimate.rangeLow ?? "—")}–${escapeHtml(latestEntry.bodyFatEstimate.rangeHigh ?? "—")}%</em>`
      : "";
    return `<article><span>${escapeHtml(definition.label)}</span><strong>${trendMetricValue(metric.latest, unit)}</strong><small>${escapeHtml(change)}</small>${estimateNote}</article>`;
  }).join("");
  renderBodyMeasurementChart(outcome);
  renderBodyCheckInHistory(outcome);
  renderProgressReview(outcome, "body-four-week-review");
  renderPlanCommand("body-plan-command");
  renderObservationVerdict("body-observation-verdict");
  const dateInput = document.getElementById("body-checkin-date");
  if (dateInput && !dateInput.value) {
    dateInput.value = todayISODate();
    dateInput.max = todayISODate();
  }
  renderBodyFatEstimate(document.getElementById("body-checkin-form"));
  renderBodyPhotoExperience();
}

function renderWeeklyBodyOutcome(aggregate) {
  if (!aggregate || typeof DominionBodyComposition === "undefined") return;
  const outcome = DominionBodyComposition.buildOutcomeModel({
    today: aggregate.weekEndDate,
    rangeDays: 84,
    performanceEntries,
    dailyStates: mergeReadinessHistory(),
    contract: readApprovedRecruitContract() || {},
    signals: {
      discipline: trendDashboardModel?.discipline?.value,
      nutrition: trendDashboardModel?.nutrition?.value,
      strengthSessions: trendDashboardModel?.training?.strengthSessions || 0
    }
  });
  const summary = DominionBodyComposition.weeklyOutcomeSummary(outcome, aggregate.weekStartDate, aggregate.weekEndDate);
  setText("weekly-outcome-state", summary.state);
  setText("weekly-outcome-detail", summary.detail);
  setText("weekly-outcome-date", summary.date ? `${summary.date} · ${summary.decision}` : "No checkpoint this week");
  const state = document.getElementById("weekly-outcome-state");
  if (state) state.className = summary.state === "CAPTURED" ? "positive" : "neutral";
}

function bodyPhotoMigrationMissing(error) {
  const message = String(error?.message || error || "").toLowerCase();
  return ["42p01", "pgrst205", "not found", "does not exist"].includes(String(error?.code || "").toLowerCase())
    || message.includes("body_progress_photos")
    || message.includes("body-progress-photos");
}

async function refreshBodyPhotoUrls() {
  bodyPhotoUrls = new Map();
  const paths = [...new Set(bodyProgressPhotos.map((item) => item.storagePath).filter(Boolean))];
  if (!paths.length) return bodyPhotoUrls;
  const supabase = await getClient();
  const { data, error } = await supabase.storage.from(DominionBodyProgress.BUCKET).createSignedUrls(paths, 3600);
  if (error) throw error;
  (data || []).forEach((item, index) => {
    const path = item.path || paths[index];
    const url = item.signedUrl || item.signedURL;
    if (path && url) bodyPhotoUrls.set(path, url);
  });
  return bodyPhotoUrls;
}

async function loadBodyProgressPhotos() {
  if (typeof DominionBodyProgress === "undefined" || !session?.user?.id) return [];
  bodyPhotoState = { loading: true, available: false, migrationRequired: false, error: null };
  try {
    const supabase = await getClient();
    const { data, error } = await supabase
      .from("body_progress_photos")
      .select("id,user_id,performance_date,angle,storage_path,content_type,size_bytes,width,height,created_at,updated_at")
      .eq("user_id", session.user.id)
      .order("performance_date", { ascending: false })
      .limit(60);
    if (error) throw error;
    bodyProgressPhotos = (data || []).map(DominionBodyProgress.normalizePhotoRecord);
    await refreshBodyPhotoUrls();
    bodyPhotoState = { loading: false, available: true, migrationRequired: false, error: null };
  } catch (error) {
    bodyProgressPhotos = [];
    bodyPhotoUrls = new Map();
    bodyPhotoState = { loading: false, available: false, migrationRequired: bodyPhotoMigrationMissing(error), error: error?.message || "Photo vault unavailable" };
  }
  renderBodyPhotoExperience();
  return bodyProgressPhotos;
}

function bodyPhotoTile(record, label, allowDelete = true) {
  const url = record?.storagePath ? bodyPhotoUrls.get(record.storagePath) : null;
  if (!record || !url) return `<article class="body-photo-tile empty"><span>${escapeHtml(label)}</span><div>Not captured</div></article>`;
  return `<article class="body-photo-tile"><span>${escapeHtml(label)}</span><img src="${escapeHtml(url)}" alt="${escapeHtml(label)} progress photo from ${record.date}" loading="lazy">${allowDelete ? `<button type="button" class="ghost danger" data-body-photo-delete="${escapeHtml(record.id || "")}" aria-label="Delete ${escapeHtml(label)} photo from ${escapeHtml(record.date)}">Delete</button>` : ""}</article>`;
}

function bodyPhotoDateColumn(group, heading) {
  if (!group) return `<section><header><span>${escapeHtml(heading)}</span><strong>No checkpoint</strong></header><div class="body-photo-angle-grid">${DominionBodyProgress.PHOTO_ANGLES.map((angle) => bodyPhotoTile(null, angle.label, false)).join("")}</div></section>`;
  return `<section><header><span>${escapeHtml(heading)}</span><strong>${escapeHtml(group.date)}</strong></header><div class="body-photo-angle-grid">${DominionBodyProgress.PHOTO_ANGLES.map((angle) => bodyPhotoTile(group.photos[angle.key], angle.label)).join("")}</div></section>`;
}

function renderBodyPhotoExperience() {
  if (typeof DominionBodyProgress === "undefined") return;
  const state = document.getElementById("body-photo-vault-state");
  const output = document.getElementById("body-photo-comparison");
  const feedback = document.getElementById("body-photo-feedback");
  const from = document.getElementById("body-photo-from-date");
  const to = document.getElementById("body-photo-to-date");
  const todayStatus = DominionBodyProgress.checkpointStatus(bodyProgressPhotos, todayISODate());
  setText("today-body-photo-count", `${todayStatus.count}/3`);
  if (!state || !output || !from || !to) return;
  if (bodyPhotoState.loading) {
    state.textContent = "CHECKING";
    output.innerHTML = '<div class="trend-chart-empty"><strong>Opening your private record</strong><span>Photos stay account-owned.</span></div>';
    return;
  }
  if (!bodyPhotoState.available) {
    state.textContent = bodyPhotoState.migrationRequired ? "ACTIVATION NEEDED" : "UNAVAILABLE";
    output.innerHTML = '<div class="trend-chart-empty"><strong>Photo vault is not active yet</strong><span>Measurements and body-fat estimates still save normally.</span></div>';
    if (feedback) feedback.textContent = "Progress photos require the private photo-vault migration.";
    return;
  }
  const comparison = DominionBodyProgress.comparison(bodyProgressPhotos, from.value || null, to.value || null);
  const options = comparison.dates.map((date) => `<option value="${escapeHtml(date)}">${escapeHtml(date)}</option>`).join("");
  const selectedFrom = comparison.from?.date || "";
  const selectedTo = comparison.to?.date || "";
  from.innerHTML = options || '<option value="">No checkpoints</option>';
  to.innerHTML = options || '<option value="">No checkpoints</option>';
  from.value = selectedFrom;
  to.value = selectedTo;
  state.textContent = comparison.dates.length ? `${comparison.dates.length} CHECKPOINT${comparison.dates.length === 1 ? "" : "S"}` : "EMPTY";
  if (!comparison.dates.length) {
    output.innerHTML = '<div class="trend-chart-empty"><strong>No progress photos yet</strong><span>Add front, side, and back with a weekly checkpoint.</span></div>';
  } else if (comparison.dates.length === 1) {
    output.innerHTML = `<div class="body-photo-single">${bodyPhotoDateColumn(comparison.to, "CURRENT")}</div>`;
  } else {
    output.innerHTML = `${bodyPhotoDateColumn(comparison.from, "FROM")}${bodyPhotoDateColumn(comparison.to, "TO")}`;
  }
  if (feedback) feedback.textContent = "Private account evidence. Compare the same pose and conditions.";
}

function renderBodyFatEstimate(form) {
  if (!form || typeof DominionBodyProgress === "undefined") return null;
  const output = form.querySelector("[data-body-fat-estimate]");
  const values = Object.fromEntries(new FormData(form).entries());
  const manual = Number(values.body_fat);
  if (Number.isFinite(manual) && manual > 0) {
    if (output) output.innerHTML = `<strong>${escapeHtml(manual.toFixed(1))}% entered</strong><span>Clear the override to use the circumference estimate.</span>`;
    return { valid: true, manual: true, value: manual, method: "SELF_REPORTED" };
  }
  const estimate = DominionBodyProgress.estimateBodyFat(values, recruitProfileForAtlas() || {});
  if (output) output.innerHTML = estimate.valid
    ? `<strong>${escapeHtml(estimate.value)}%</strong><span>Estimated range ${escapeHtml(estimate.rangeLow)}–${escapeHtml(estimate.rangeHigh)}% · Navy circumference method</span>`
    : `<strong>Estimate pending</strong><span>${escapeHtml(estimate.label)}</span>`;
  return estimate;
}

function previewBodyProgressPhoto(input) {
  const preview = input?.closest("label")?.querySelector("[data-body-photo-preview]");
  if (!preview) return;
  if (preview.dataset.objectUrl) URL.revokeObjectURL(preview.dataset.objectUrl);
  const file = input.files?.[0] || null;
  if (!file) {
    preview.textContent = "Add photo";
    delete preview.dataset.objectUrl;
    return;
  }
  const validation = DominionBodyProgress.validatePhotoFile(file);
  if (!validation.valid) {
    input.value = "";
    preview.textContent = validation.errors[0];
    return;
  }
  const url = URL.createObjectURL(file);
  preview.dataset.objectUrl = url;
  preview.innerHTML = `<img src="${escapeHtml(url)}" alt="Selected ${escapeHtml(input.dataset.bodyPhotoAngle.toLowerCase())} progress photo preview"><small>Replace</small>`;
}

function resetBodyProgressPhotoPreviews(form) {
  form?.querySelectorAll("[data-body-photo-preview]").forEach((preview) => {
    if (preview.dataset.objectUrl) URL.revokeObjectURL(preview.dataset.objectUrl);
    delete preview.dataset.objectUrl;
    preview.textContent = "Add photo";
  });
}

async function prepareBodyProgressPhoto(file) {
  const validation = DominionBodyProgress.validatePhotoFile(file);
  if (!validation.valid) throw new Error(validation.errors[0]);
  let bitmap;
  let sourceUrl = null;
  if (typeof createImageBitmap === "function") {
    bitmap = await createImageBitmap(file, { imageOrientation: "from-image" });
  } else {
    sourceUrl = URL.createObjectURL(file);
    bitmap = await new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = () => reject(new Error("Photo could not be opened."));
      image.src = sourceUrl;
    });
  }
  const maxEdge = 1600;
  const scale = Math.min(1, maxEdge / Math.max(bitmap.width, bitmap.height));
  const width = Math.max(1, Math.round(bitmap.width * scale));
  const height = Math.max(1, Math.round(bitmap.height * scale));
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d", { alpha: false });
  context.fillStyle = "#0a0a0a";
  context.fillRect(0, 0, width, height);
  context.drawImage(bitmap, 0, 0, width, height);
  bitmap.close?.();
  if (sourceUrl) URL.revokeObjectURL(sourceUrl);
  const blob = await new Promise((resolve, reject) => canvas.toBlob((value) => value ? resolve(value) : reject(new Error("Photo processing failed.")), "image/jpeg", 0.86));
  return { blob, width, height };
}

async function uploadBodyProgressPhotos(form, date) {
  if (!form || typeof DominionBodyProgress === "undefined") return { count: 0, errors: [] };
  const selections = [...form.querySelectorAll("input[data-body-photo-angle]")]
    .map((input) => ({ angle: input.dataset.bodyPhotoAngle, file: input.files?.[0] || null }))
    .filter((item) => item.file);
  if (!selections.length) return { count: 0, errors: [] };
  if (!session?.user?.id) return { count: 0, errors: ["Sign in to save private progress photos."] };
  const supabase = await getClient();
  const saved = [];
  const errors = [];
  for (const selection of selections) {
    let path = null;
    try {
      const prepared = await prepareBodyProgressPhoto(selection.file);
      path = DominionBodyProgress.photoPath(session.user.id, date, selection.angle);
      const upload = await supabase.storage.from(DominionBodyProgress.BUCKET).upload(path, prepared.blob, { upsert: true, contentType: "image/jpeg", cacheControl: "3600" });
      if (upload.error) throw upload.error;
      const record = {
        user_id: session.user.id,
        performance_date: date,
        angle: selection.angle,
        storage_path: path,
        content_type: "image/jpeg",
        size_bytes: prepared.blob.size,
        width: prepared.width,
        height: prepared.height,
        capture_protocol: "STANDARD_WEEKLY",
        updated_at: new Date().toISOString()
      };
      const response = await supabase.from("body_progress_photos").upsert(record, { onConflict: "user_id,performance_date,angle" }).select("*").single();
      if (response.error) throw response.error;
      saved.push(DominionBodyProgress.normalizePhotoRecord(response.data));
    } catch (error) {
      if (path) await supabase.storage.from(DominionBodyProgress.BUCKET).remove([path]);
      errors.push(`${selection.angle.toLowerCase()}: ${error?.message || "upload failed"}`);
    }
  }
  if (saved.length) await loadBodyProgressPhotos();
  return { count: saved.length, errors };
}

async function deleteBodyProgressPhoto(photoId) {
  const record = bodyProgressPhotos.find((item) => String(item.id) === String(photoId));
  if (!record || !window.confirm(`Delete the ${record.angle.toLowerCase()} photo from ${record.date}?`)) return;
  const supabase = await getClient();
  const storage = await supabase.storage.from(DominionBodyProgress.BUCKET).remove([record.storagePath]);
  if (storage.error) throw storage.error;
  const metadata = await supabase.from("body_progress_photos").delete().eq("id", record.id).eq("user_id", session.user.id);
  if (metadata.error) throw metadata.error;
  bodyProgressPhotos = bodyProgressPhotos.filter((item) => item.id !== record.id);
  bodyPhotoUrls.delete(record.storagePath);
  renderBodyPhotoExperience();
  setText("body-photo-feedback", "Photo deleted.");
}

async function deleteBodyProgressPhotosForDate(date) {
  const rows = bodyProgressPhotos.filter((item) => item.date === date);
  if (!rows.length || !session?.user?.id) return;
  const supabase = await getClient();
  const paths = rows.map((item) => item.storagePath).filter(Boolean);
  if (paths.length) await supabase.storage.from(DominionBodyProgress.BUCKET).remove(paths);
  await supabase.from("body_progress_photos").delete().eq("user_id", session.user.id).eq("performance_date", date);
  bodyProgressPhotos = bodyProgressPhotos.filter((item) => item.date !== date);
  paths.forEach((path) => bodyPhotoUrls.delete(path));
  renderBodyPhotoExperience();
}

function bodyCheckInInput(formId = "body-checkin-form") {
  const form = typeof formId === "string" ? document.getElementById(formId) : formId;
  if (!form) return {};
  const values = Object.fromEntries(new FormData(form).entries());
  const manual = Number(values.body_fat);
  if (typeof DominionBodyProgress !== "undefined" && (!Number.isFinite(manual) || manual <= 0)) {
    const estimate = DominionBodyProgress.estimateBodyFat(values, recruitProfileForAtlas() || {});
    if (estimate.valid) {
      values.body_fat = estimate.value;
      values.body_fat_method = estimate.method;
      values.body_fat_estimated = true;
      values.body_fat_range_low = estimate.rangeLow;
      values.body_fat_range_high = estimate.rangeHigh;
    }
  } else if (Number.isFinite(manual) && manual > 0) {
    values.body_fat_method = "SELF_REPORTED";
    values.body_fat_estimated = false;
  }
  return values;
}

function bodyCheckInUuid() {
  return globalThis.crypto?.randomUUID?.() || null;
}

async function persistBodyCheckIn(form, feedbackId = "body-checkin-feedback") {
  if (typeof DominionBodyComposition === "undefined") return;
  const input = bodyCheckInInput(form);
  const existing = performanceEntries.find((entry) => entry.domain === "body_metrics" && entry.activityCode === "body_composition_checkin" && entry.performanceDate === input.date);
  const result = DominionBodyComposition.buildCheckInEntry(input, {
    today: todayISODate(),
    now: new Date().toISOString(),
    userId: session?.user?.id || null,
    existingId: existing?.id || bodyCheckInUuid(),
    createdAt: existing?.createdAt || null
  });
  if (!result.valid) {
    setText(feedbackId, result.errors[0]);
    return false;
  }
  const validation = validatePerformanceEntry(result.entry);
  if (!validation.valid) {
    setText(feedbackId, validation.errors[0]?.message || "That checkpoint could not be validated.");
    return false;
  }
  setText(feedbackId, "Saving checkpoint…");
  const payload = buildPerformancePersistencePayload(validation.entry, session?.user?.id || null);
  let saved = hydratePerformanceEntry(payload);
  let storage = "LOCAL";
  try {
    const supabase = await getClient();
    const response = await supabase.from("performance_entries").upsert(payload, { onConflict: "id" }).select("*").single();
    if (response.error) throw response.error;
    saved = hydratePerformanceEntry(response.data || payload);
    storage = "SUPABASE";
  } catch (_) {}
  performanceEntries = [saved, ...performanceEntries.filter((entry) => entry.id !== saved.id && !(entry.domain === "body_metrics" && entry.activityCode === "body_composition_checkin" && entry.performanceDate === saved.performanceDate))];
  performanceStorageMode = storage;
  performanceSaveState = storage === "SUPABASE" ? "saved" : "locally saved";
  saveLocalPerformanceEntries(performanceEntries);
  renderPerformanceSection(performanceEntries, performanceStorageMode, performanceSaveState);
  if (trendAnalyticsContext) renderTrendsAnalytics(trendAnalyticsContext.inspections, trendAnalyticsContext.dailyRecords, trendAnalyticsContext.storageMode);
  if (weeklyInspection) renderWeeklyBodyOutcome(weeklyInspection);
  const photoResult = await uploadBodyProgressPhotos(form, saved.performanceDate);
  const unit = input.unit || "in";
  form?.reset();
  resetBodyProgressPhotoPreviews(form);
  const dateInput = form?.querySelector('[name="date"]');
  const unitInput = form?.querySelector('[name="unit"]');
  if (dateInput) dateInput.value = todayISODate();
  if (unitInput) unitInput.value = unit;
  renderBodyFatEstimate(form);
  const outcome = buildCurrentBodyOutcomeModel();
  renderTodayBodyCheckpoint(outcome);
  if (outcome) renderBodyOutcome(outcome);
  const photoMessage = photoResult.count
    ? ` ${photoResult.count} private photo${photoResult.count === 1 ? "" : "s"} saved.`
    : photoResult.errors.length
      ? ` Measurements saved; photos need attention (${photoResult.errors[0]}).`
      : "";
  setText(feedbackId, (storage === "SUPABASE" ? "Checkpoint saved to your account. Atlas updated the outcome signal." : "Checkpoint saved on this device; account sync will retry.") + photoMessage);
  return true;
}

async function saveBodyCheckIn(event) {
  event?.preventDefault();
  return persistBodyCheckIn(event?.currentTarget || document.getElementById("body-checkin-form"), "body-checkin-feedback");
}

async function saveTodayBodyCheckIn(event) {
  event?.preventDefault();
  const saved = await persistBodyCheckIn(event?.currentTarget || document.getElementById("today-body-checkin-form"), "today-body-checkin-feedback");
  if (saved) {
    const capture = document.getElementById("today-body-capture");
    if (capture) capture.open = false;
  }
}

function editBodyCheckIn(entryId) {
  const entry = performanceEntries.find((item) => String(item.id) === String(entryId));
  if (!entry || typeof DominionBodyComposition === "undefined") return;
  const normalized = DominionBodyComposition.normalizeBodyEntry(entry);
  const form = document.getElementById("body-checkin-form");
  if (!form) return;
  form.elements.date.value = normalized.date || todayISODate();
  form.elements.unit.value = normalized.unit || "in";
  DominionBodyComposition.CIRCUMFERENCE_KEYS.forEach((key) => { form.elements[key].value = DominionBodyComposition.displayCircumference(normalized.values[key], normalized.unit) ?? ""; });
  form.elements.body_fat.value = normalized.values.body_fat ?? "";
  form.elements.notes.value = normalized.notes || "";
  form.closest("details").open = true;
  form.scrollIntoView({ behavior: "smooth", block: "center" });
  renderBodyFatEstimate(form);
  setText("body-checkin-feedback", `Editing ${normalized.date}. Saving will replace that date’s checkpoint.`);
}

async function deleteBodyCheckIn(entryId) {
  if (!entryId || !window.confirm("Delete this body checkpoint? This action cannot be undone.")) return;
  const removed = performanceEntries.find((entry) => String(entry.id) === String(entryId));
  const removedDate = removed?.performanceDate || removed?.performance_date || null;
  performanceEntries = performanceEntries.filter((entry) => String(entry.id) !== String(entryId));
  saveLocalPerformanceEntries(performanceEntries);
  try {
    const supabase = await getClient();
    const response = await supabase.from("performance_entries").delete().eq("id", entryId);
    if (response.error) throw response.error;
  } catch (_) {}
  if (removedDate) await deleteBodyProgressPhotosForDate(removedDate);
  renderPerformanceSection(performanceEntries, performanceStorageMode, performanceSaveState);
  if (trendAnalyticsContext) renderTrendsAnalytics(trendAnalyticsContext.inspections, trendAnalyticsContext.dailyRecords, trendAnalyticsContext.storageMode);
  if (weeklyInspection) renderWeeklyBodyOutcome(weeklyInspection);
  renderTodayBodyCheckpoint();
  setText("body-checkin-feedback", "Checkpoint deleted.");
}

async function resolveBodyOutcomeReview(action) {
  if (typeof DominionBodyComposition === "undefined") return false;
  const outcome = buildCurrentBodyOutcomeModel();
  try {
    const record = DominionBodyComposition.resolveOutcomeReview(outcome?.review, action, {
      resolvedAt: new Date().toISOString(),
      userId: session?.user?.id || null
    });
    const synced = await saveBodyOutcomeReview(record);
    const next = buildCurrentBodyOutcomeModel();
    renderTodayBodyCheckpoint(next);
    renderBodyOutcome(next);
    const message = record.status === "AUTHORIZED"
      ? `Outcome review authorized${synced ? " and saved to your account" : " on this device"}. No plan or target changed.`
      : `Current plan held${synced ? " and saved to your account" : " on this device"}. Atlas will keep monitoring.`;
    setText("today-body-checkin-feedback", message);
    setText("body-checkin-feedback", message);
    return true;
  } catch (error) {
    setText("today-body-checkin-feedback", error?.message || "That outcome decision could not be saved.");
    setText("body-checkin-feedback", error?.message || "That outcome decision could not be saved.");
    return false;
  }
}

async function handleBodyOutcomeAction(event) {
  const action = event.target.closest("button[data-body-review-action]");
  if (action) {
    action.disabled = true;
    try { await resolveBodyOutcomeReview(action.dataset.bodyReviewAction); }
    finally { action.disabled = false; }
    return true;
  }
  const route = event.target.closest("button[data-body-review-route]");
  if (route) {
    const section = route.dataset.bodyReviewRoute || "trends";
    if (section === "trends") setTrendView("body");
    setActiveSection(section);
    window.history.replaceState(null, "", `#${section}`);
    return true;
  }
  return false;
}

function renderProgramTrends(model, domainTrends, trajectory, storageMode) {
  trendDashboardModel = model;
  setText("trend-command-signal", model.coaching.signal);
  setText("trend-command-detail", model.coaching.detail);
  const action = document.getElementById("trend-command-action");
  action.textContent = model.coaching.action.label;
  action.href = `#${model.coaching.action.section}`;
  action.dataset.section = model.coaching.action.section;
  setText("trend-evidence-score", `${model.evidence.score}%`);
  setText("trend-evidence-label", model.evidence.label);
  setText("trend-evidence-sources", `${model.evidence.sourceCount} of ${model.evidence.possibleSources} signals`);
  document.getElementById("trend-evidence-ring").style.setProperty("--trend-evidence", model.evidence.score);
  document.querySelectorAll("[data-trend-range]").forEach((button) => button.setAttribute("aria-pressed", Number(button.dataset.trendRange) === model.rangeDays ? "true" : "false"));

  document.getElementById("trend-kpi-grid").innerHTML = model.kpis.map((item) => `<article class="trend-kpi ${escapeHtml(item.tone)}" data-kpi="${escapeHtml(item.id)}">
    <header><span>${escapeHtml(item.label)}</span>${trendSparkBars(item.series)}</header>
    <strong>${trendMetricValue(item.value, item.suffix)}</strong>
    <small>${escapeHtml(item.deltaLabel || "Signal not established")}</small>
    <em>${escapeHtml(item.evidence || "No evidence")}</em>
  </article>`).join("");

  setText("trend-win", model.coaching.win);
  setText("trend-watch", model.coaching.watch);
  setText("trend-next", model.coaching.next);
  renderTrendPrimaryChart(model);

  const training = model.training;
  document.getElementById("trend-training-grid").innerHTML = [
    ["Strength", training.strengthSessions, "days"],
    ["Running", training.runMiles, "miles"],
    ["Core", training.coreSessions, "sessions"],
    ["Active", training.totalSessionDays, "days"]
  ].map(([label, value, unit]) => `<article><span>${label}</span><strong>${value}</strong><small>${unit} · ${model.rangeLabel}</small></article>`).join("");

  const readiness = model.readiness;
  document.getElementById("trend-recovery-grid").innerHTML = [
    ["Energy", trendMetricValue(readiness.value, "/10"), "latest 7d"],
    ["Sleep", trendMetricValue(readiness.sleepAverage, " hr"), "range average"],
    ["Resting HR", trendMetricValue(readiness.rhrAverage, " bpm"), "range average"],
    ["HRV", trendMetricValue(readiness.hrvAverage, " ms"), "range average"]
  ].map(([label, value, note]) => `<article><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`).join("");

  const bodyOutcome = model.bodyComposition || buildCurrentBodyOutcomeModel(model);
  renderBodyOutcome(bodyOutcome);
  renderTodayBodyCheckpoint(bodyOutcome);
  const windowDates = trajectory.window.map((item) => item.weekStartDate);
  setText("trend-window", windowDates.length ? `${windowDates[0]} — ${windowDates.at(-1)} · ${windowDates.length} finalized week${windowDates.length === 1 ? "" : "s"}` : "No finalized scored window yet.");
  setText("analytics-storage", storageMode === "SUPABASE" ? "ACCOUNT EVIDENCE" : "DEVICE EVIDENCE");
  setText("trend-method-version", model.version);
  document.getElementById("trend-domain-grid").innerHTML = COMPLIANCE_DOMAINS.map((key) => `<div class="trend-domain-card ${domainTrends[key].direction.toLowerCase().replaceAll(" ", "-")}"><span>${COMPLIANCE_DOMAIN_LABELS[key]}</span><strong>${domainTrends[key].direction}</strong><small>${domainTrends[key].slope === null ? "Learning" : `${domainTrends[key].slope.toFixed(1)} pts/wk`}</small></div>`).join("");
  setTrendView(trendActiveView);
}

function renderTrendsAnalytics(inspections, dailyRecords, storageMode) {
  inspectionHistory = canonicalFinalizedInspections(inspections);
  const currentRange = getInspectionWeekRange(todayISODate());
  const currentAggregate = aggregateWeeklyCompliance(dailyRecords, currentRange.weekStartDate);
  const hasFinalizedCurrentWeek = sortInspectionHistory(inspections).some((item) => item.weekStartDate === currentRange.weekStartDate && item.finalizedAt);
  const provisional = currentAggregate.counts.assessedObservations > 0 && !hasFinalizedCurrentWeek ? currentAggregate : null;
  const trajectory = deriveTrajectoryState(inspectionHistory, { windowSize: Math.max(4, Math.round(trendRangeDays / 7)) });
  const domainTrends = calculateDomainTrends(inspectionHistory, { windowSize: Math.max(4, Math.round(trendRangeDays / 7)) });
  if (typeof DominionTrends === "undefined") {
    renderLegacyTrendsAnalytics(inspections, dailyRecords, storageMode);
    return;
  }
  trendAnalyticsContext = { inspections, dailyRecords, storageMode };
  const trendInputs = {
    today: todayISODate(),
    rangeDays: trendRangeDays,
    inspections: inspectionHistory,
    dailyStates: mergeReadinessHistory(),
    dailyRecords,
    performanceEntries,
    strengthHistory: readStrengthHistory(),
    coreHistory: readCoreHistory(),
    nutritionDays: trendNutritionHistory(84),
    nutritionTargets: currentNutritionBaseTargets(todayISODate())
  };
  const baseModel = DominionTrends.buildProgramTrendModel(trendInputs);
  const bodyComposition = typeof DominionBodyComposition === "undefined" ? null : DominionBodyComposition.buildOutcomeModel({
    today: todayISODate(),
    rangeDays: trendRangeDays,
    performanceEntries,
    dailyStates: trendInputs.dailyStates,
    contract: readApprovedRecruitContract() || {},
    signals: {
      discipline: baseModel.discipline.value,
      nutrition: baseModel.nutrition.value,
      strengthSessions: baseModel.training.strengthSessions
    },
    priorReview: readBodyOutcomeReview()
  });
  const model = DominionTrends.buildProgramTrendModel({ ...trendInputs, bodyComposition });
  renderProgramTrends(model, domainTrends, trajectory, storageMode);
  renderCommandCenterOverview(dailyState ? evaluateReadiness(dailyState) : null, weeklyInspection || provisional || {}, trajectory.state);
  renderRankSection();
  renderReviewHub();
}

async function loadTrendsAnalytics() {
  try {
    const supabase = await getClient();
    const results = await Promise.all([
      supabase.from("weekly_inspections").select("week_start_date,week_end_date,weekly_discipline_score,evidence_coverage,domain_scores,inspection_status,finalized_at").eq("user_id", session.user.id).order("week_start_date", { ascending: true }),
      supabase.from("daily_compliance").select(COMPLIANCE_COLUMNS).eq("user_id", session.user.id).lte("compliance_date", todayISODate()).order("compliance_date", { ascending: true })
    ]);
    if (results[0].error) throw results[0].error;
    if (results[1].error) throw results[1].error;
    renderTrendsAnalytics(results[0].data || [], results[1].data || [], "SUPABASE");
  } catch (_) {
    const local = loadLocalAnalyticsHistory();
    renderTrendsAnalytics(local.inspections, local.dailyRecords, "LOCAL FALLBACK");
  }
}
